def _parse_version(v: str) -> tuple:
    if not v:
        return (0,)
    v = v.strip().lstrip("vV").strip()
    import re as _re
    parts = _re.findall(r'\d+', v)
    return tuple(int(p) for p in parts) if parts else (0,)

def is_newer_version(latest: str, current: str) -> bool:
    """True, если latest новее current."""

    return _parse_version(latest) > _parse_version(current)


class OllamaStatusWorker(QThread):
    """Асинхронно опрашивает состояние Ollama, чтобы не блокировать UI."""

    status_ready = Signal(dict)

    def __init__(self, host: str, parent=None):
        super().__init__(parent)
        self.host = host

    def run(self):
        try:
            mgr = OllamaManager(self.host)
            if not mgr.is_running(timeout=1.5):
                self.status_ready.emit({"server_running": False})
                return
            models = mgr.list_models()
            loaded = mgr.list_running()
            self.status_ready.emit({
                "server_running": True,
                "installed_count": len(models),
                "loaded_models": loaded,
            })
        except Exception as e:
            self.status_ready.emit({"server_running": False, "error": str(e)})


class OllamaManager:
    """Управление сервером Ollama и его моделями (нативный API)."""

    def __init__(self, host: str = OLLAMA_HOST_DEFAULT):
        self.host = host.rstrip('/')
        self._ollama_process = None

    @staticmethod
    def _find_ollama_executable(settings: dict = None) -> str:
        """Ищет ollama.exe на системе.
        Порядок поиска:
          1. Путь из настроек Echos (settings["ollama_path"]).
          2. Системный PATH (shutil.which).
          3. Стандартные места установки.
          4. Реестр Windows.
        Возвращает полный путь к ollama.exe или "ollama", если не найдено.
        """

        import shutil as _shutil

        # 1. Путь из настроек Echos — высший приоритет
        if settings:
            custom = (settings.get("ollama_path") or "").strip().strip('"').strip("'")
            if custom and os.path.isfile(custom):
                return custom

        # 2. Системный PATH
        found = _shutil.which("ollama")
        if found:
            return found

        # 3. Стандартные места
        candidates = []

        local_appdata = os.environ.get("LOCALAPPDATA", "")
        if local_appdata:
            candidates.append(
                os.path.join(local_appdata, "Programs", "Ollama", "ollama.exe")
            )

        for env_var in ("ProgramFiles", "ProgramFiles(x86)", "ProgramW6432"):
            base = os.environ.get(env_var, "")
            if base:
                candidates.append(os.path.join(base, "Ollama", "ollama.exe"))

        for c in candidates:
            if c and os.path.isfile(c):
                return c

        # 4. Реестр Windows
        if os.name == 'nt':
            try:
                import winreg
                for hive, key_path in (
                    (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Ollama"),
                    (winreg.HKEY_CURRENT_USER, r"SOFTWARE\Ollama"),
                ):
                    try:
                        with winreg.OpenKey(hive, key_path) as key:
                            install_dir, _ = winreg.QueryValueEx(key, "InstallLocation")
                            if install_dir:
                                exe = os.path.join(install_dir, "ollama.exe")
                                if os.path.isfile(exe):
                                    return exe
                    except (FileNotFoundError, OSError):
                        continue
            except ImportError:
                pass

        # Ничего не нашли — вернём голое имя, авось PATH подхватит
        return "ollama"

    def is_running(self, timeout: float = 1.5) -> bool:
        """Проверяет, отвечает ли сервер Ollama."""

        try:
            resp = requests.get(f"{self.host}/api/version", timeout=timeout)
            return resp.status_code == 200
        except Exception:
            return False

    def get_version(self) -> Optional[str]:
        try:
            resp = requests.get(f"{self.host}/api/version", timeout=2)
            if resp.status_code == 200:
                return resp.json().get("version")
        except Exception:
            pass
        return None

    def list_models(self) -> List[Dict[str, Any]]:
        """Список установленных моделей (GET /api/tags)."""

        try:
            resp = requests.get(f"{self.host}/api/tags", timeout=5)
            if resp.status_code == 200:
                return resp.json().get("models", [])
        except Exception as e:
            logger.warning(f"[OllamaManager] Ошибка list_models: {e}")
        return []

    def list_running(self) -> List[Dict[str, Any]]:
        """Список моделей, загруженных в память (GET /api/ps)."""

        try:
            resp = requests.get(f"{self.host}/api/ps", timeout=5)
            if resp.status_code == 200:
                return resp.json().get("models", [])
        except Exception:
            pass
        return []

    def pull_model(self, model_name: str, progress_callback=None, cancel_flag=None):
        """Скачивает модель с прогрессом (POST /api/pull).
        Возвращает кортеж (успех: bool, сообщение: str)."""

        try:
            with requests.post(
                    f"{self.host}/api/pull",
                    json={"name": model_name, "stream": True},
                    stream=True,
                    timeout=(10, None)
            ) as resp:
                if resp.status_code != 200:
                    return False, f"HTTP {resp.status_code}"
                for line in resp.iter_lines():
                    if cancel_flag and cancel_flag():
                        return False, "Отменено пользователем"
                    if not line:
                        continue
                    try:
                        data = json.loads(line.decode('utf-8'))
                    except json.JSONDecodeError:
                        continue
                    if progress_callback:
                        progress_callback(data)
                    if data.get("error"):
                        return False, str(data["error"])
                    if data.get("status") == "success":
                        return True, "Готово"
            return True, "Готово"
        except Exception as e:
            return False, str(e)

    def delete_model(self, model_name: str) -> bool:
        """Удаляет модель (DELETE /api/delete)."""

        try:
            resp = requests.delete(
                f"{self.host}/api/delete",
                json={"name": model_name},
                timeout=10
            )
            return resp.status_code == 200
        except Exception:
            return False

    def unload_model(self, model_name: str) -> bool:
        """Выгружает модель из памяти Ollama (keep_alive=0)."""

        # Пробуем несколько вариантов, т.к. разные версии Ollama понимают разный формат
        variants = [
            {"model": model_name, "keep_alive": 0},
            {"model": model_name, "keep_alive": "0s"},
            {"model": model_name, "keep_alive": "0"},
        ]
        for payload in variants:
            try:
                resp = requests.post(
                    f"{self.host}/api/generate",
                    json=payload,
                    timeout=15,
                    stream=False,
                )
                if resp.status_code == 200:
                    # Проверяем, что модель действительно выгрузилась
                    time.sleep(0.3)
                    running = {m.get("name") for m in self.list_running()}
                    if model_name not in running:
                        # Модель выгружена (или её там не было)
                        return True
            except Exception:
                continue
        return False

    def get_model_size_bytes(self, model_name: str) -> int:
        """Возвращает размер модели в байтах (или 0, если не найдена)."""

        for m in self.list_models():
            name = m.get("name", "")
            if name == model_name or name.split(":")[0] == model_name.split(":")[0]:
                return m.get("size", 0)
        return 0

    def start_server(self, ollama_path: str) -> bool:
        """Запускает Ollama. Возвращает True, если сервер поднялся за 40 секунд."""

        if self.is_running():
            return True

        # Чистим путь от кавычек и пробелов
        ollama_path = (ollama_path or "").strip().strip('"').strip("'")

        # Если путь не задан или не существует — ищем сами
        if not ollama_path or not os.path.isfile(ollama_path):
            ollama_path = self._find_ollama_executable()

        logger.info(f"[OllamaManager] Запуск: {ollama_path}")

        # Убиваем зависшие процессы Ollama только если они реально есть.
        # taskkill /F для несуществующего процесса занимает ~500 мс —
        # а при автозапуске это выглядит как подвисание UI.
        try:
            if os.name == 'nt':
                import subprocess as _sp
                creation_flags = 0x08000000
                # Быстрая проверка через tasklist — есть ли процесс вообще
                for proc_name in ("ollama app.exe", "ollama.exe"):
                    check = _sp.run(
                        ["tasklist", "/FI", f"IMAGENAME eq {proc_name}", "/NH"],
                        capture_output=True, text=True,
                        creationflags=creation_flags, timeout=2
                    )
                    # Если в выводе встречается имя процесса — он запущен
                    if proc_name.lower() in (check.stdout or "").lower():
                        _sp.run(
                            ["taskkill", "/F", "/IM", proc_name],
                            capture_output=True,
                            creationflags=creation_flags, timeout=3
                        )
                # Убираем sleep(0.5) — он не нужен, если процесс не убивали
        except Exception as e:
            logger.warning(f"[OllamaManager] taskkill ошибка: {e}")

        # Запускаем `ollama serve` напрямую
        try:
            creation_flags = 0x08000000 if os.name == 'nt' else 0
            self._ollama_process = subprocess.Popen(
                [ollama_path, "serve"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=creation_flags
            )
            logger.info(f"[OllamaManager] PID процесса: {self._ollama_process.pid}")

            # Ждём до 40 секунд
            for i in range(80):
                time.sleep(0.5)
                if self.is_running(timeout=1.0):
                    logger.info(f"[OllamaManager] Сервер поднялся за {(i + 1) * 0.5:.1f} сек")
                    return True

            logger.warning("[OllamaManager] Таймаут: сервер не отвечает на 11434")
            return False
        except FileNotFoundError:
            logger.warning(f"[OllamaManager] Не найден: {ollama_path}")
            return False
        except Exception as e:
            logger.warning(f"[OllamaManager] Ошибка запуска: {e}")
            return False

    def shutdown_server(self, wait_check: bool = True) -> bool:
        """Полностью останавливает Ollama: и наш процесс, и системный.
        wait_check=False — не проверять результат (быстрее, для закрытия программы)."""

        # 1. Если процесс запущен нами — останавливаем корректно
        if self._ollama_process is not None:
            try:
                self._ollama_process.terminate()
                self._ollama_process.wait(timeout=3)
            except Exception:
                try:
                    self._ollama_process.kill()
                except Exception:
                    pass
            self._ollama_process = None

        # 2. Принудительно убиваем системные процессы Ollama
        try:
            if os.name == 'nt':
                creation_flags = 0x08000000  # CREATE_NO_WINDOW
                for proc_name in ("ollama app.exe", "ollama.exe"):
                    subprocess.run(
                        ["taskkill", "/F", "/IM", proc_name],
                        capture_output=True,
                        creationflags=creation_flags,
                        timeout=5
                    )
            else:
                subprocess.run(["pkill", "-f", "ollama"], capture_output=True, timeout=5)
        except Exception as e:
            logger.warning(f"[OllamaManager] Ошибка shutdown_server: {e}")

        if not wait_check:
            return True

        # 3. Проверяем, что сервер действительно недоступен
        time.sleep(1.0)
        return not self.is_running(timeout=2)

    def is_managed_process(self) -> bool:
        """True, если процесс запущен самой программой (а не пользователем)."""

        return self._ollama_process is not None and self._ollama_process.poll() is None

    @staticmethod
    def _detect_chat_template(model_name: str):
        """Определяет шаблон чата и stop-токены по имени модели.
        Возвращает кортеж (template: str, stops: list[str], family: str)."""

        name = model_name.lower()

        # ChatML — Qwen, DeepSeek, Yi, OpenHermes, Nous-Hermes-2, etc.
        if any(k in name for k in ("qwen", "deepseek", "yi-", "yi_", "hermes", "openhermes",
                                   "nous", "chatml", "dolphin")):
            template = (
                '{{- if .System }}<|im_start|>system\n'
                '{{ .System }}<|im_end|>\n'
                '{{ end }}{{- range .Messages }}'
                '{{- if eq .Role "user" }}<|im_start|>user\n'
                '{{ .Content }}<|im_end|>\n'
                '<|im_start|>assistant\n'
                '{{ else if eq .Role "assistant" }}{{ .Content }}<|im_end|>\n'
                '{{ end }}{{- end }}'
            )
            return template, ["<|im_start|>", "<|im_end|>"], "chatml"

        # Llama 3 / 3.1 / 3.2
        if "llama-3" in name or "llama3" in name or "llama_3" in name:
            template = (
                '{{- if .System }}<|start_header_id|>system<|end_header_id|>\n\n'
                '{{ .System }}<|eot_id|>{{ end }}'
                '{{- range .Messages }}'
                '{{- if eq .Role "user" }}<|start_header_id|>user<|end_header_id|>\n\n'
                '{{ .Content }}<|eot_id|>'
                '<|start_header_id|>assistant<|end_header_id|>\n\n'
                '{{ else if eq .Role "assistant" }}{{ .Content }}<|eot_id|>'
                '{{ end }}{{- end }}'
            )
            return template, ["<|start_header_id|>", "<|end_header_id|>", "<|eot_id|>"], "llama3"

        # Mistral / Mixtral / Codestral
        if any(k in name for k in ("mistral", "mixtral", "codestral")):
            template = (
                '{{- if .System }}{{ .System }}\n{{ end }}'
                '{{- range .Messages }}'
                '{{- if eq .Role "user" }}[INST] {{ .Content }} [/INST]'
                '{{ else if eq .Role "assistant" }} {{ .Content }}</s>'
                '{{ end }}{{- end }}'
            )
            return template, ["</s>", "[INST]"], "mistral"

        # Gemma / Gemma 2
        if "gemma" in name:
            template = (
                '{{- if .System }}{{ .System }}\n{{ end }}'
                '{{- range .Messages }}'
                '{{- if eq .Role "user" }}<start_of_turn>user\n'
                '{{ .Content }}<end_of_turn>\n'
                '<start_of_turn>model\n'
                '{{ else if eq .Role "assistant" }}{{ .Content }}<end_of_turn>\n'
                '{{ end }}{{- end }}'
            )
            return template, ["<start_of_turn>", "<end_of_turn>"], "gemma"

        # Phi-3 / Phi-4
        if "phi" in name:
            template = (
                '{{- if .System }}<|system|>\n'
                '{{ .System }}<|end|>\n{{ end }}'
                '{{- range .Messages }}'
                '{{- if eq .Role "user" }}<|user|>\n'
                '{{ .Content }}<|end|>\n'
                '<|assistant|>\n'
                '{{ else if eq .Role "assistant" }}{{ .Content }}<|end|>\n'
                '{{ end }}{{- end }}'
            )
            return template, ["<|end|>", "<|user|>", "<|assistant|>", "<|system|>"], "phi"

        # Дефолт — ChatML (самый универсальный)
        template = (
            '{{- if .System }}<|im_start|>system\n'
            '{{ .System }}<|im_end|>\n'
            '{{ end }}{{- range .Messages }}'
            '{{- if eq .Role "user" }}<|im_start|>user\n'
            '{{ .Content }}<|im_end|>\n'
            '<|im_start|>assistant\n'
            '{{ else if eq .Role "assistant" }}{{ .Content }}<|im_end|>\n'
            '{{ end }}{{- end }}'
        )
        return template, ["<|im_start|>", "<|im_end|>"], "chatml"

    def import_gguf(self, gguf_path: str, model_name: str, template: str,
                    stops: list, num_ctx: int = 8192,
                    temperature: float = 0.7) -> tuple:
        """Импортирует GGUF-файл в Ollama через `ollama create` с автоматически сгенерированным Modelfile.
        Возвращает (успех: bool, сообщение: str, вывод_команды: str)."""

        import tempfile

        # Готовим содержимое Modelfile
        # FROM с прямыми слэшами (важно для Windows)
        gguf_normalized = gguf_path.replace("\\", "/")
        modelfile_lines = [
            f'FROM {gguf_normalized}',
            '',
            f'PARAMETER temperature {temperature}',
            'PARAMETER top_p 0.9',
            'PARAMETER repeat_penalty 1.1',
            f'PARAMETER num_ctx {num_ctx}',
        ]
        for stop in stops:
            modelfile_lines.append(f'PARAMETER stop "{stop}"')
        modelfile_lines.append('')
        modelfile_lines.append(f'TEMPLATE """{template}"""')
        modelfile_content = "\n".join(modelfile_lines)

        # Записываем во временный файл
        try:
            fd, mf_path = tempfile.mkstemp(prefix="echos_modelfile_", suffix=".txt")
            os.close(fd)
            with open(mf_path, 'w', encoding='utf-8', newline='\n') as f:
                f.write(modelfile_content)
        except Exception as e:
            return False, f"Ошибка создания Modelfile: {e}", ""

        # Ищем ollama.exe
        ollama_exe = self._find_ollama_executable()

        # Запускаем ollama create
        try:
            creation_flags = 0x08000000 if os.name == 'nt' else 0
            result = subprocess.run(
                [ollama_exe, "create", model_name, "-f", mf_path],
                capture_output=True,
                text=True,
                timeout=600,
                creationflags=creation_flags
            )
            output = (result.stdout or "") + (result.stderr or "")
            if result.returncode == 0:
                return True, f"Модель «{model_name}» импортирована", output
            return False, f"Ошибка ollama create (код {result.returncode})", output
        except FileNotFoundError:
            return False, "ollama.exe не найден. Установите Ollama.", ""
        except subprocess.TimeoutExpired:
            return False, "Превышено время ожидания (10 мин)", ""
        except Exception as e:
            return False, f"Ошибка запуска: {e}", ""
        finally:
            try:
                os.remove(mf_path)
            except Exception as e:
                logger.warning(f"[Ollama] Не удалось удалить временный Modelfile {mf_path}: {e}")


class OllamaWorker(QThread):
    """Поток генерации ответа через нативный API Ollama (/api/chat)."""

    chunk_received = Signal(str)
    finished_ok = Signal(str, str)
    error_occurred = Signal(str)
    stopped = Signal()
    retry_attempt = Signal(int, int, str)
    tool_calls_requested = Signal(list, str, str)

    def __init__(self, host: str, model: str, messages: List[Dict[str, Any]],
                 params: Dict[str, Any], stream: bool = True,
                 keep_alive: str = "5m", tools: list = None):
        super().__init__()
        self.host = host.rstrip('/')
        self.model = model
        self.messages = messages
        self.params = params
        self.stream = stream
        self.keep_alive = keep_alive
        self.tools = tools or []
        self._stop_requested = False
        self._response = None
        self.finish_reason = ""
        self.buffer = ""
        self.buffer_limit = 150
        self._tool_calls_buffer = []

    def stop(self):
        self._stop_requested = True
        if self._response:
            try:
                self._response.close()
            except Exception:
                pass

    def _flush_buffer(self):
        if self.buffer:
            self.chunk_received.emit(self.buffer)
            self.buffer = ""

    def _build_options(self) -> Dict[str, Any]:
        """Переводит параметры из формата OpenAI в формат Ollama."""

        opts = {}
        if "temperature" in self.params:
            opts["temperature"] = self.params["temperature"]
        if "top_p" in self.params:
            opts["top_p"] = self.params["top_p"]
        if "top_k" in self.params:
            opts["top_k"] = self.params["top_k"]
        if "repeat_penalty" in self.params:
            opts["repeat_penalty"] = self.params["repeat_penalty"]
        if "max_tokens" in self.params:
            opts["num_predict"] = self.params["max_tokens"]
        if "num_ctx" in self.params and self.params["num_ctx"]:
            opts["num_ctx"] = self.params["num_ctx"]
        return opts

    def _convert_multimodal(self, messages: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Конвертирует OpenAI-формат мультимодальных сообщений в формат Ollama.
        Ollama ожидает поле 'images' со списком base64-строк."""

        converted = []
        for m in messages:
            content = m.get("content")
            if isinstance(content, list):
                text_parts = []
                images = []
                for part in content:
                    if not isinstance(part, dict):
                        continue
                    ptype = part.get("type")
                    if ptype == "text":
                        text_parts.append(part.get("text", ""))
                    elif ptype == "image_url":
                        url = part.get("image_url", {}).get("url", "")
                        if url.startswith("data:"):
                            comma = url.find(",")
                            if comma > 0:
                                images.append(url[comma + 1:])
                new_msg = {"role": m["role"], "content": "\n".join(text_parts)}
                if images:
                    new_msg["images"] = images
                converted.append(new_msg)
            else:
                converted.append(m)
        return converted

    def run(self):
        url = f"{self.host}/api/chat"

        # Отделяем system-сообщения (Ollama принимает их отдельным полем 'system')
        system_parts = []
        chat_messages = []
        for m in self.messages:
            if m.get("role") == "system":
                system_parts.append(m.get("content", ""))
            else:
                chat_messages.append(m)

        # Конвертируем мультимодальный формат
        chat_messages = self._convert_multimodal(chat_messages)

        payload = {
            "model": self.model,
            "messages": chat_messages,
            "stream": self.stream,
            "options": self._build_options(),
            "keep_alive": self.keep_alive,
        }
        if self.tools:
            payload["tools"] = self.tools
        if system_parts:
            payload["system"] = "\n".join(system_parts)

        max_retries = 3
        retry_delay = 2
        attempt = 0

        while attempt < max_retries:
            try:
                if self.stream:
                    with requests.post(
                            url, json=payload, stream=True,
                            timeout=(10, 300)
                    ) as resp:
                        self._response = resp
                        if resp.status_code != 200:
                            self.error_occurred.emit(f"HTTP {resp.status_code}: {resp.text}")
                            return

                        full_text = ""
                        full_reasoning = ""

                        try:
                            for line in resp.iter_lines():
                                if self._stop_requested:
                                    self.stopped.emit()
                                    return
                                if not line:
                                    continue
                                try:
                                    data = json.loads(line.decode('utf-8'))
                                except json.JSONDecodeError:
                                    continue

                                if data.get("error"):
                                    self.error_occurred.emit(str(data["error"]))
                                    return

                                msg = data.get("message", {})
                                content = msg.get("content", "")
                                thinking = msg.get("thinking", "")

                                # Ollama отдаёт tool_calls в message.tool_calls
                                if msg.get("tool_calls"):
                                    self._tool_calls_buffer.extend(msg["tool_calls"])

                                if thinking:
                                    full_reasoning += thinking
                                if content:
                                    full_text += content
                                    self.buffer += content
                                    if len(self.buffer) >= self.buffer_limit:
                                        self._flush_buffer()

                                if data.get("done"):
                                    dr = data.get("done_reason", "")
                                    self.finish_reason = dr if dr else "stop"
                                    break

                        except (requests.exceptions.ChunkedEncodingError,
                                requests.exceptions.ConnectionError,
                                requests.exceptions.ReadTimeout,
                                ConnectionResetError,
                                BrokenPipeError,
                                OSError,
                                AttributeError) as e:
                            if self._stop_requested:
                                self.stopped.emit()
                                return
                            logger.warning(f"[OllamaWorker] Обрыв соединения: {type(e).__name__}: {e}")
                            if full_text.strip():
                                self._flush_buffer()
                                self.finished_ok.emit(full_text, full_reasoning)
                                return
                            self.error_occurred.emit(
                                f"Соединение прервано.\nПричина: {type(e).__name__}"
                            )
                            return

                        self._flush_buffer()
                        self._response = None

                        if self._tool_calls_buffer:
                            self.tool_calls_requested.emit(
                                self._tool_calls_buffer, full_text, full_reasoning
                            )
                            return

                        if full_text.strip() or full_reasoning.strip():
                            self.finished_ok.emit(full_text, full_reasoning)
                        else:
                            self.error_occurred.emit("Модель вернула пустой ответ.")
                        return
                else:
                    payload["stream"] = False
                    resp = requests.post(url, json=payload, timeout=600)
                    self._response = resp
                    if resp.status_code != 200:
                        self.error_occurred.emit(f"HTTP {resp.status_code}: {resp.text}")
                        return
                    if self._stop_requested:
                        self.stopped.emit()
                        return
                    data = resp.json()
                    msg = data.get("message", {})
                    content = msg.get("content", "")
                    thinking = msg.get("thinking", "")
                    self._response = None
                    if content.strip() or thinking.strip():
                        self.finished_ok.emit(content, thinking)
                    else:
                        self.error_occurred.emit("Модель вернула пустой ответ.")
                    return

            except requests.exceptions.RequestException as e:
                attempt += 1
                if self._stop_requested:
                    self.stopped.emit()
                    return
                if attempt < max_retries:
                    self.retry_attempt.emit(attempt, max_retries, str(e))
                    time.sleep(retry_delay)
                    retry_delay *= 2
                    continue
                self.error_occurred.emit(
                    f"Не удалось получить ответ после {max_retries} попыток.\n"
                    f"Последняя ошибка: {str(e)}"
                )
                return


class OllamaImportGGUFDialog(QDialog):
    """Диалог импорта GGUF-файла в Ollama с авто-генерацией Modelfile."""

    def __init__(self, main_window, parent=None):
        super().__init__(parent)
        self.main_window = main_window
        self.setWindowIcon(QIcon(main_window.resource_path("Image/Ollama_window.png")))
        self.setWindowTitle("Импорт GGUF в Ollama")
        self.setModal(True)
        self.resize(650, 550)

        self.gguf_path = ""
        self.manager = OllamaManager(
            host=main_window.settings.get("ollama_host", OLLAMA_HOST_DEFAULT)
        )

        # Таймер для отображения времени импорта
        self._import_start_time = None
        self._import_timer = QTimer(self)
        self._import_timer.setInterval(1000)
        self._import_timer.timeout.connect(self._update_import_progress)

        # Создаём UI ОДИН раз
        self.init_ui()

    def init_ui(self):
        layout = QVBoxLayout(self)

        # --- Выбор GGUF-файла ---
        file_group = QGroupBox("GGUF-файл")
        file_layout = QVBoxLayout(file_group)
        file_row = QHBoxLayout()
        self.edit_gguf_path = QLineEdit()
        self.edit_gguf_path.setPlaceholderText("Путь к .gguf файлу...")
        self.edit_gguf_path.setReadOnly(True)
        btn_browse = QPushButton("Выбрать...")
        btn_browse.clicked.connect(self.browse_gguf)
        file_row.addWidget(self.edit_gguf_path)
        file_row.addWidget(btn_browse)
        file_layout.addLayout(file_row)

        self.file_info = QLabel("")
        self.file_info.setStyleSheet("color: #888; font-size: 11px;")
        file_layout.addWidget(self.file_info)
        layout.addWidget(file_group)

        # --- Имя модели ---
        name_group = QGroupBox("Имя модели")
        name_layout = QVBoxLayout(name_group)
        self.edit_model_name = QLineEdit()
        self.edit_model_name.setPlaceholderText("Например: qwen-9b-local")
        name_layout.addWidget(self.edit_model_name)
        hint = QLabel("Под этим именем модель появится в ollama list и будет доступна в Echos.")
        hint.setStyleSheet("color: #888; font-size: 11px;")
        name_layout.addWidget(hint)
        layout.addWidget(name_group)

        # --- Параметры ---
        params_group = QGroupBox("Параметры")
        params_layout = QFormLayout(params_group)

        self.spin_ctx = QSpinBox()
        self.spin_ctx.setRange(512, 131072)
        self.spin_ctx.setValue(8192)
        self.spin_ctx.setSingleStep(1024)
        params_layout.addRow("Размер контекста (num_ctx):", self.spin_ctx)

        self.spin_temp = QDoubleSpinBox()
        self.spin_temp.setRange(0.0, 2.0)
        self.spin_temp.setSingleStep(0.05)
        self.spin_temp.setValue(0.7)
        params_layout.addRow("Temperature:", self.spin_temp)

        # Автоопределение шаблона
        self.combo_template = QComboBox()
        self.combo_template.addItem("Авто (по имени модели)", "auto")
        self.combo_template.addItem("ChatML (Qwen, DeepSeek, Yi)", "chatml")
        self.combo_template.addItem("Llama 3", "llama3")
        self.combo_template.addItem("Mistral / Mixtral", "mistral")
        self.combo_template.addItem("Gemma / Gemma 2", "gemma")
        self.combo_template.addItem("Phi-3 / Phi-4", "phi")
        params_layout.addRow("Шаблон чата:", self.combo_template)

        layout.addWidget(params_group)

        # --- Превью Modelfile ---
        preview_group = QGroupBox("Modelfile (генерируется автоматически)")
        preview_layout = QVBoxLayout(preview_group)
        self.preview_edit = QTextEdit()
        self.preview_edit.setReadOnly(True)
        self.preview_edit.setStyleSheet(
            "font-family: Consolas, monospace; font-size: 11px;"
        )
        self.preview_edit.setMaximumHeight(180)
        preview_layout.addWidget(self.preview_edit)
        layout.addWidget(preview_group)

        # --- Прогресс импорта ---
        self.progress_bar = QProgressBar()
        self.progress_bar.setRange(0, 0)   # indeterminate — бегающая полоска
        self.progress_bar.setVisible(False)
        layout.addWidget(self.progress_bar)

        self.progress_label = QLabel("")
        self.progress_label.setStyleSheet(
            "color: #888; font-size: 11px; font-style: italic;"
        )
        self.progress_label.setAlignment(Qt.AlignCenter)
        self.progress_label.setVisible(False)
        layout.addWidget(self.progress_label)

        # --- Кнопки ---
        btn_box = QHBoxLayout()
        self.btn_import = QPushButton("Импортировать")
        self.btn_import.setEnabled(False)
        self.btn_import.clicked.connect(self.do_import)
        btn_cancel = QPushButton("Отмена")
        btn_cancel.clicked.connect(self.reject)
        btn_box.addStretch()
        btn_box.addWidget(self.btn_import)
        btn_box.addWidget(btn_cancel)
        layout.addLayout(btn_box)

        # Обновляем превью при изменениях
        self.edit_model_name.textChanged.connect(self.update_preview)
        self.combo_template.currentIndexChanged.connect(self.update_preview)
        self.spin_ctx.valueChanged.connect(self.update_preview)
        self.spin_temp.valueChanged.connect(self.update_preview)

    def browse_gguf(self):
        """Открывает диалог выбора GGUF-файла."""

        path, _ = QFileDialog.getOpenFileName(
            self,
            "Выбрать GGUF-файл",
            "",
            "GGUF модели (*.gguf);;Все файлы (*)",
            options=QFileDialog.DontUseNativeDialog,
        )
        if not path:
            return

        # Проверяем, что это не mmproj
        fname = os.path.basename(path).lower()
        if fname.startswith("mmproj") or "mmproj" in fname:
            reply = QMessageBox.question(
                self, "Это проекционный файл",
                "Выбранный файл похож на vision-проектор (mmproj).\n\n"
                "Он не подойдёт как основная модель. Продолжить?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No
            )
            if reply != QMessageBox.Yes:
                return

        # Заполняем поля
        self.gguf_path = path
        self.edit_gguf_path.setText(path)
        try:
            size_mb = os.path.getsize(path) / (1024 * 1024)
            self.file_info.setText(f"Размер: {size_mb:.1f} МБ")
        except OSError:
            self.file_info.setText("Размер: не определён")

        base = os.path.splitext(os.path.basename(path))[0]
        suggested = base.replace("_", "-").replace(" ", "-").lower()
        self.edit_model_name.setText(suggested)

        self.btn_import.setEnabled(True)
        self.update_preview()

        # === ЖЁСТКАЯ ПЕРЕРИСОВКА ===
        # 1. Сбрасываем и пересобираем стиль всего диалога
        self.style().unpolish(self)
        self.style().polish(self)
        for w in (self.edit_gguf_path, self.file_info,
                  self.edit_model_name, self.btn_import, self.preview_edit):
            w.style().unpolish(w)
            w.style().polish(w)
            w.update()
            w.repaint()

        # 2. Трюк с размером окна — форсирует полный relayout
        w_size = self.size()
        self.resize(w_size.width(), w_size.height() + 1)
        self.resize(w_size.width(), w_size.height())

        # 3. Форсируем обработку событий
        QApplication.processEvents()
        self.update()
        self.repaint()
        QApplication.processEvents()

        # 4. Возвращаем фокус диалогу
        self.raise_()
        self.activateWindow()

    def _get_template_data(self):
        """Возвращает (template, stops) по выбору combo и имени модели."""

        choice = self.combo_template.currentData()
        model_name = self.edit_model_name.text().strip() or "model"

        if choice == "auto":
            return self.manager._detect_chat_template(model_name)

        # Явный выбор
        mapping = {
            "chatml": "qwen",  # чтобы _detect вернул ChatML
            "llama3": "llama-3",
            "mistral": "mistral",
            "gemma": "gemma",
            "phi": "phi",
        }
        fake_name = mapping.get(choice, "qwen")
        return self.manager._detect_chat_template(fake_name)

    def update_preview(self):
        """Обновляет превью Modelfile."""

        if not self.gguf_path:
            self.preview_edit.setPlainText("Сначала выберите .gguf файл.")
            return

        template, stops, family = self._get_template_data()

        gguf_normalized = self.gguf_path.replace("\\", "/")
        lines = [
            f'FROM {gguf_normalized}',
            '',
            f'PARAMETER temperature {self.spin_temp.value()}',
            'PARAMETER top_p 0.9',
            'PARAMETER repeat_penalty 1.1',
            f'PARAMETER num_ctx {self.spin_ctx.value()}',
        ]
        for stop in stops:
            lines.append(f'PARAMETER stop "{stop}"')
        lines.append('')
        lines.append(f'TEMPLATE """{template}"""')

        self.preview_edit.setPlainText("\n".join(lines))

    def _start_import_progress(self):
        """Показывает прогресс-бар и запускает таймер."""

        self._import_start_time = time.time()
        self.progress_bar.setVisible(True)
        self.progress_label.setVisible(True)
        self.progress_label.setText("⏳ Идёт импорт... 0 сек")
        self._import_timer.start()

    def _update_import_progress(self):
        """Обновляет текст с прошедшим временем."""

        if self._import_start_time is None:
            return
        elapsed = int(time.time() - self._import_start_time)

        # Форматируем: 45 сек, 1 мин 20 сек, 3 мин 05 сек
        if elapsed < 60:
            time_str = f"{elapsed} сек"
        else:
            minutes = elapsed // 60
            seconds = elapsed % 60
            time_str = f"{minutes} мин {seconds:02d} сек"

        # Подсказка: на 30-й секунде показываем, что это может занять несколько минут
        if elapsed < 30:
            hint = "Обычно занимает 1–3 минуты в зависимости от размера модели"
        elif elapsed < 180:
            hint = "Идёт копирование файла модели в хранилище Ollama..."
        else:
            hint = "Большая модель — процесс может занять до 10 минут. Не закрывайте окно."

        self.progress_label.setText(f"⏳ Идёт импорт... {time_str}\n{hint}")

    def _stop_import_progress(self):
        """Скрывает прогресс-бар и останавливает таймер."""

        self._import_timer.stop()
        self.progress_bar.setVisible(False)
        self.progress_label.setVisible(False)
        self._import_start_time = None

    def do_import(self):
        if not self.gguf_path:
            return
        model_name = self.edit_model_name.text().strip()
        if not model_name:
            QMessageBox.warning(self, "Ошибка", "Введите имя модели.")
            return
        if not os.path.exists(self.gguf_path):
            QMessageBox.warning(self, "Ошибка", "Файл не найден.")
            return

        # Проверяем, нет ли модели с таким именем
        existing = [m.get("name", "") for m in self.manager.list_models()]
        if model_name in existing or f"{model_name}:latest" in existing:
            reply = QMessageBox.question(
                self, "Модель уже существует",
                f"Модель «{model_name}» уже есть в Ollama. Перезаписать?",
                QMessageBox.Yes | QMessageBox.No, QMessageBox.No
            )
            if reply != QMessageBox.Yes:
                return

        # Запускаем в отдельном потоке, чтобы не блокировать UI
        self.btn_import.setEnabled(False)
        self.btn_import.setText("Импорт...")

        # Показываем прогресс
        self._start_import_progress()

        QApplication.processEvents()

        template, stops, family = self._get_template_data()

        # Безопасная передача результата через Signal
        class ImportThread(QThread):
            done = Signal(bool, str, str)

            def __init__(self, mgr, path, name, tmpl, st, nctx, temp):
                super().__init__()
                self.mgr = mgr
                self.path = path
                self.name = name
                self.tmpl = tmpl
                self.st = st
                self.nctx = nctx
                self.temp = temp

            def run(self):
                ok, msg, output = self.mgr.import_gguf(
                    self.path, self.name, self.tmpl, self.st,
                    num_ctx=self.nctx, temperature=self.temp
                )
                self.done.emit(ok, msg, output)

        self._import_thread = ImportThread(
            self.manager, self.gguf_path, model_name, template, stops,
            self.spin_ctx.value(), self.spin_temp.value()
        )
        self._import_thread.done.connect(self._on_import_done)
        self._import_thread.start()

    def _on_import_done(self, ok: bool, message: str, output: str):
        self._stop_import_progress()
        self.btn_import.setEnabled(True)
        self.btn_import.setText("Импортировать")

        if ok:
            # Сохраняем имя до закрытия диалога
            model_name = self.edit_model_name.text().strip()

            # Показываем уведомление СНАЧАЛА
            QMessageBox.information(
                self,
                "Готово",
                f"Модель «{model_name}» успешно импортирована в Ollama.\n\n"
                f"Она появится в списке моделей и будет доступна в Echos.\n\n"
                f"Чтобы использовать её в чате:\n"
                f"1. Откройте или создайте чат\n"
                f"2. Нажмите ⚙ (Параметры генерации)\n"
                f"3. В выпадающем списке «Модель» выберите «{model_name}»"
            )

            # Теперь закрываем диалог
            self.accept()
        else:
            dlg = QMessageBox(self)
            dlg.setIcon(QMessageBox.Warning)
            dlg.setWindowTitle("Ошибка импорта")
            dlg.setText(message)
            if output:
                dlg.setDetailedText(output)
            dlg.exec()


class OllamaModelsFetchWorker(QThread):
    """Фоновый воркер: получает version, список моделей и запущенные модели."""

    data_ready = Signal(dict)

    def __init__(self, host: str, parent=None):
        super().__init__(parent)
        self.host = host

    def run(self):
        result = {"server_running": False}
        try:
            mgr = OllamaManager(self.host)
            if not mgr.is_running(timeout=1.5):
                self.data_ready.emit(result)
                return

            result["server_running"] = True
            result["version"] = mgr.get_version() or "?"
            result["models"] = mgr.list_models()
            result["running_names"] = [
                m.get("name", "") for m in mgr.list_running()
            ]
        except Exception as e:
            result["error"] = str(e)
        self.data_ready.emit(result)


class OllamaModelsDialog(QDialog):
    """Диалог управления моделями Ollama: список, скачивание, удаление."""

    def __init__(self, main_window, parent=None):
        super().__init__(parent)
        self.main_window = main_window
        self.setWindowIcon(QIcon(self.main_window.resource_path("Image/Ollama_window.png")))
        self.setWindowTitle("Менеджер моделей Ollama")
        self.setModal(True)
        self.resize(750, 560)
        self.manager = OllamaManager(
            host=main_window.settings.get("ollama_host", OLLAMA_HOST_DEFAULT)
        )
        self._pull_thread = None
        self._cancel_pull = False
        self._refreshing = False
        self.init_ui()
        # Окно показывается мгновенно, модели подтягиваются через 50 мс
        QTimer.singleShot(50, self.refresh_models)

    def init_ui(self):
        layout = QVBoxLayout(self)

        status_layout = QHBoxLayout()

        self.status_icon = QLabel()
        self.status_icon.setFixedSize(12, 12)
