        self.status_label = QLabel("Проверка сервера...")
        self.btn_start = QPushButton("Запустить Ollama")
        self.btn_start.clicked.connect(self.start_server)
        self.btn_refresh = QPushButton("Обновить")
        self.btn_refresh.clicked.connect(self.refresh_models)
        status_layout.addWidget(self.status_label)
        status_layout.addStretch()
        status_layout.addWidget(self.btn_start)
        status_layout.addWidget(self.btn_refresh)
        layout.addLayout(status_layout)

        self.list_widget = QListWidget()
        self.list_widget.setIconSize(QSize(12, 12))
        self.list_widget.setContextMenuPolicy(Qt.CustomContextMenu)
        self.list_widget.customContextMenuRequested.connect(self.show_context_menu)
        self.list_widget.currentItemChanged.connect(self.on_selection_changed)
        layout.addWidget(self.list_widget, stretch=2)

        self.info_label = QLabel("")
        self.info_label.setWordWrap(True)
        self.info_label.setStyleSheet("color: #666; padding: 4px;")
        layout.addWidget(self.info_label)

        # Панель скачивания
        pull_group = QGroupBox("Скачать модель")
        pull_layout = QVBoxLayout(pull_group)
        pull_row = QHBoxLayout()
