        pull_row.addWidget(self.btn_pull)
        pull_layout.addLayout(pull_row)

        self.pull_progress = QProgressBar()
        self.pull_progress.setVisible(False)
        self.pull_progress.setRange(0, 100)
        pull_layout.addWidget(self.pull_progress)

        self.pull_status = QLabel("")
        self.pull_status.setStyleSheet("color: #666; font-size: 11px;")
        pull_layout.addWidget(self.pull_status)
        layout.addWidget(pull_group)

        btn_box = QHBoxLayout()
        self.btn_delete = QPushButton("Удалить с диска")
        self.btn_delete.clicked.connect(self.delete_selected)
        self.btn_unload = QPushButton("Выгрузить из памяти")
        self.btn_unload.setToolTip("Освободить VRAM/RAM, не удаляя модель")
        self.btn_unload.clicked.connect(self.unload_selected)

        self.btn_load = QPushButton("Загрузить в память")
        self.btn_load.setToolTip("Предзагрузить модель в VRAM/RAM, чтобы первый запрос был мгновенным")
        self.btn_load.setEnabled(False)
        self.btn_load.clicked.connect(self.load_selected)

        self.btn_shutdown = QPushButton(" Выключить Ollama")
        self.btn_shutdown.setIcon(QIcon(self.main_window.resource_path("Image/Off.png")))
