        self.btn_import_gguf = QPushButton(" Импортировать GGUF...")
        self.btn_import_gguf.setIcon(QIcon(self.main_window.resource_path("Image/Import_2.png")))
        self.btn_import_gguf.setIconSize(QSize(16, 16))
