    def _init_chats_index(self):
        """Загружает индекс из файла или запускает фоновую сборку."""
        if self.chats_index is None:
            return
        if self.chats_index.load():
            return
        # Нет файла — строим в фоне
        if self.chats:
            self._chats_index_worker = ChatsIndexBuildWorker(
                self.chats_index, self.chats, parent=self
            )
            self._chats_index_worker.finished_ok.connect(
                lambda: self.statusBar().showMessage(
                    f"Индекс чатов готов: "
                    f"{len(self.chats_index.documents)} сообщений", 5000
                )
            )
            self._chats_index_worker.start()

    def _touch_fernet_timer(self):
        """Продлевает таймер автоблокировки.

        Вызывается при любой операции, требующей мастер-ключ
        (расшифровка чата, сохранение зашифрованного чата, отправка
        сообщения в зашифрованный чат и т. п.).
        """
        if not hasattr(self, '_fernet_lock_timer'):
            return
        if self._fernet is None:
            return
        if self._fernet_timeout_ms <= 0:
            return  # 0 = никогда
        self._fernet_lock_timer.start(self._fernet_timeout_ms)

    def _lock_fernet(self):
        """Выгружает мастер-ключ из памяти после простоя.

        Также запирает все ранее расшифрованные чаты в текущей сессии,
        чтобы при переключении на них пользователь снова ввёл пароль.
        Текущий открытый чат остаётся видимым до следующего переключения.
        """
        was_unlocked = self._fernet is not None or bool(self._session_unlocked)

        # Сбрасываем мастер-ключ
        self._fernet = None

        # Сбрасываем пароль текущего зашифрованного чата
        if getattr(self, '_current_chat_password', None):
            self._current_chat_password = None

        # Помечаем все зашифрованные чаты как «запертые» — при следующем
        # переключении на любой из них пароль потребуется ввести заново.
        for c in self.chats:
            if c.get('encrypted', False):
                self._session_unlocked.discard(c['filepath'])
                c['locked'] = True

        if was_unlocked:
            self.logger.info(
                "[Crypto] Мастер-ключ выгружен из памяти "
                f"(простой более {self._fernet_timeout_ms // 60000} мин)"
            )
            self.statusBar().showMessage(
                "🔒 Мастер-ключ выгружен из памяти. "
                "Для доступа к зашифрованным чатам потребуется пароль.",
                8000
            )

    def transcribe_file_dialog(self):
        """Диалог выбора файла + запуск транскрибации в фоне."""

        if not FASTER_WHISPER_AVAILABLE:
            QMessageBox.warning(
                self, "STT недоступен",
                "Библиотека faster-whisper не установлена.\n\n"
                "Установите командой:\n"
                "  pip install faster-whisper\n\n"
                "Также нужен ffmpeg (gyan.dev/ffmpeg/builds → bin в PATH)."
            )
            return

        # Проверка: не идёт ли уже транскрибация
        if getattr(self, '_transcribe_worker', None) is not None \
                and self._transcribe_worker.isRunning():
            QMessageBox.information(self, "Занято", "Транскрибация уже идёт.")
            return

        dlg = QFileDialog(self, "Выберите аудио или видео", "")
        dlg.setOption(QFileDialog.DontUseNativeDialog, True)
        dlg.setWindowIcon(QIcon("Image/Microphone_dialog.png"))
        dlg.setFileMode(QFileDialog.ExistingFile)
        dlg.setNameFilters([
            "Аудио/видео (*.mp3 *.wav *.m4a *.ogg *.flac *.aac *.mp4 *.mkv *.mov *.avi *.webm)",
            "Все файлы (*)"
        ])
        if not dlg.exec():
            return
        selected = dlg.selectedFiles()
        if not selected:
            return
        filepath = selected[0]
        if not filepath:
            return

        # Размер файла (защита от гигантских)
        try:
            size_mb = os.path.getsize(filepath) / (1024 * 1024)
            if size_mb > 500:
                reply = QMessageBox.question(
                    self, "Большой файл",
                    f"Файл {size_mb:.0f} МБ. Обработка может занять 10+ минут.\n\n"
                    "Продолжить?",
                    QMessageBox.Yes | QMessageBox.No, QMessageBox.No
                )
                if reply != QMessageBox.Yes:
                    return
        except Exception:
            pass

        model_size = self.settings.get("whisper_model_size", "small")
        language = self.settings.get("whisper_language", "ru")

        self.statusBar().showMessage(f"🎵 Транскрибирую: {os.path.basename(filepath)}")

        self._transcribe_worker = TranscribeWorker(
            filepath, model_size=model_size, language=language, parent=self
        )
        self._transcribe_worker.progress.connect(
            lambda msg: QTimer.singleShot(0, lambda: self.statusBar().showMessage(f"🎵 {msg}"))
        )
        self._transcribe_worker.finished_ok.connect(self._on_transcribe_done)
        self._transcribe_worker.error_occurred.connect(self._on_transcribe_error)
        self._transcribe_worker.start()

        # Кнопка «Стоп» временно заменяет «Отправить»?
        # Или просто блокируем кнопку
        self.btn_transcribe.setEnabled(False)

    def _on_transcribe_done(self, text: str):
        """Вставляет распознанный текст в поле ввода."""

        self.btn_transcribe.setEnabled(True)
        self.statusBar().showMessage(f"✅ Транскрибация завершена ({len(text)} символов)", 5000)

        # Вставляем в поле ввода
        current = self.input_edit.toPlainText()
        if current.strip():
            self.input_edit.setPlainText(current + "\n\n" + text)
        else:
            self.input_edit.setPlainText(text)

        # Прокручиваем поле ввода вниз
        cursor = self.input_edit.textCursor()
        cursor.movePosition(QTextCursor.End)
        self.input_edit.setTextCursor(cursor)
        self.input_edit.setFocus()

    def _on_transcribe_error(self, err: str):
        """Показывает ошибку транскрибации."""

        self.btn_transcribe.setEnabled(True)
        self.statusBar().showMessage("Ошибка транскрибации", 5000)
        QMessageBox.warning(self, "Ошибка транскрибации", err)

    def _preload_rag_models(self):
        """Запускает фоновую предзагрузку моделей RAG."""

        if getattr(self, '_rag_preloader', None) is not None:
            return
        print("[RAG Preload] Старт фоновой предзагрузки моделей")
        self._rag_preloader = RAGModelsPreloader(self.rag_manager, parent=self)
        self._rag_preloader.progress.connect(
            lambda msg: print(f"[RAG Preload] {msg}")
        )
        self._rag_preloader.finished_ok.connect(
            lambda: print("[RAG Preload] Готово")
        )
        self._rag_preloader.start()

    def _show_minimap_smooth(self):
        """Показывает панель вопросов — мгновенно, без анимаций."""

        if not hasattr(self, 'minimap_panel'):
            return
        panel = self.minimap_panel
        if panel.isVisible():
            return
        panel.setVisible(True)
        # Пересчитываем обои под новую ширину чата
        QTimer.singleShot(20, self._reapply_bg_after_minimap)

    def _hide_minimap_smooth(self):
        """Скрывает панель вопросов — мгновенно."""

        if not hasattr(self, 'minimap_panel'):
            return
        panel = self.minimap_panel
        if not panel.isVisible():
            return
        panel.setVisible(False)
        QTimer.singleShot(20, self._reapply_bg_after_minimap)

    def _reapply_bg_after_minimap(self):
        """Пересчитывает обои после изменения ширины чата."""

        try:
            if 0 <= self.current_chat_index < len(self.chats):
                self.apply_chat_background(self.chats[self.current_chat_index])
            else:
                self.apply_chat_background(None)
        except Exception as e:
            self._log_silent("Пересчёт фона после мини-карты", e)

    def toggle_minimap_panel(self):
        """Переключает видимость панели вопросов."""

        if not hasattr(self, 'minimap_panel'):
            return

        new_state = not self.settings.get("show_minimap_panel", False)
        self.settings["show_minimap_panel"] = new_state
        self.save_settings()

        # Применяем настройку
        self._update_minimap()

        self.statusBar().showMessage(
            "Панель вопросов включена" if new_state else "Панель вопросов выключена",
            2000
        )

    def _save_window_geometry_now(self):
        """Сохраняет текущую геометрию окна в настройки."""

        if not self.settings.get("remember_window_geometry", True):
            return
        try:
            # Если окно maximized/fullscreen — сохраняем нормализованный размер
            if self.isMaximized() or self.isFullScreen():
                geom = self.normalGeometry()
            else:
                geom = self.geometry()

            # Сохраняем размер и позицию отдельно
            self.settings["window_width"] = geom.width()
            self.settings["window_height"] = geom.height()
            self.settings["window_x"] = geom.x()
            self.settings["window_y"] = geom.y()
            self.settings["window_maximized"] = self.isMaximized()
            self.save_settings()
        except Exception as e:
            self._log_silent("Сохранение геометрии окна", e)

    def _on_window_moved_or_resized(self, event):
        """Перезапускает таймер сохранения геометрии (дебаунс 500 мс)."""

        super().resizeEvent(event) if 'resize' in str(event) else None
        if hasattr(self, '_geometry_save_timer'):
            self._geometry_save_timer.start(500)

    def _restore_window_geometry(self):
        """Восстанавливает размер и позицию окна."""
        if not self.settings.get("remember_window_geometry", True):
            logger.debug("[Geometry] Восстановление отключено в настройках")
            return

        try:
            w = self.settings.get("window_width")
            h = self.settings.get("window_height")
            x = self.settings.get("window_x")
            y = self.settings.get("window_y")
            was_maximized = self.settings.get("window_maximized", False)

            if w and h:
                # Проверка: не за экраном ли
                screen = QApplication.primaryScreen().availableGeometry()
                if x is not None and y is not None:
                    if not screen.intersects(QRect(x, y, w, h)):
                        # Сбрасываем в центр
                        x = screen.center().x() - w // 2
                        y = screen.center().y() - h // 2

                self.resize(w, h)
                if x is not None and y is not None:
                    self.move(x, y)
                if was_maximized:
                    self.showMaximized()

                logger.info(f"[Geometry] Восстановлено: {w}x{h} at ({x}, {y}), maximized={was_maximized}")
        except Exception as e:
            self._log_silent("Восстановление геометрии окна", e)

    def _reapply_chat_bg_on_resize(self):
        if self.current_chat_index < 0:
            return
        chat = self.chats[self.current_chat_index]
        # Пересчитываем только если есть картинка или цвет
        if chat.get('background_image') or chat.get('background_color'):
            self.apply_chat_background(chat)

    def _refresh_ollama_models_cache(self):
        """Запускает фоновое обновление кэша моделей Ollama."""

        if self.settings.get("llm_provider") != "ollama":
            return
        if self._ollama_models_cache_worker is not None \
                and self._ollama_models_cache_worker.isRunning():
            return

        host = self.settings.get("ollama_host", OLLAMA_HOST_DEFAULT)
        self._ollama_models_cache_worker = OllamaModelsCacheWorker(host, parent=None)
        self._ollama_models_cache_worker.models_ready.connect(self._on_ollama_models_cache_ready)
        self._ollama_models_cache_worker.start()

    def _on_ollama_models_cache_ready(self, models: list):
        """Сохраняет список моделей в кэш."""

        self._ollama_models_cache = models
        self._ollama_models_cache_time = time.time()
        logger.debug(f"[OllamaCache] Обновлён кэш: {len(models)} моделей")

    def _get_cached_ollama_models(self) -> list:
        """Возвращает кэш моделей. Если кэш пуст — запускает фоновое обновление."""

        if not self._ollama_models_cache:
            self._refresh_ollama_models_cache()
        return self._ollama_models_cache

    def _ensure_chat_model_valid(self, chat):
        """Проверяет модель чата по КЭШУ (без HTTP-запросов). Если её нет — подставляет глобальную."""

        if self.settings.get("llm_provider") != "ollama":
            return

        available = self._get_cached_ollama_models()

        # Если кэш пуст — не трогаем (обновление уже идёт в фоне)
        if not available:
            return

        chat_model = chat.get('model', '').strip()
        global_model = self.settings.get('model', '').strip()

        if not chat_model:
            if global_model:
                chat['model'] = global_model
                self.save_chat_by_filepath(chat['filepath'])
            return

        def normalize(n):
            return n.split(":")[0] if ":" in n else n

        available_norm = {normalize(n) for n in available}
        chat_norm = normalize(chat_model)

        if chat_norm in available_norm:
            return

        global_norm = normalize(global_model)
        if global_model and global_norm in available_norm:
            chat['model'] = global_model
            self.save_chat_by_filepath(chat['filepath'])
            self.statusBar().showMessage(
                f"⚠ Модель «{chat_model}» не найдена. Использую «{global_model}»",
                10000
            )
        elif available:
            fallback = sorted(available)[0]
            chat['model'] = fallback
            self.save_chat_by_filepath(chat['filepath'])
            self.statusBar().showMessage(
                f"⚠ Модель «{chat_model}» не найдена. Использую «{fallback}»",
                10000
            )

    def _apply_titlebar_theme(self, dark: bool):
        """Перекрашивает нативный заголовок окна Windows в тёмный/светлый."""

        if os.name != 'nt':
            return
        try:
            hwnd = int(self.winId())
            value = ctypes.c_int(1 if dark else 0)
            # Атрибут 20 — Windows 10 20H1+, 19 — более старые версии
            for attr in (20, 19):
                ctypes.windll.dwmapi.DwmSetWindowAttribute(
                    hwnd, attr,
                    ctypes.byref(value),
                    ctypes.sizeof(value)
                )
            # Принудительно перерисовать заголовок
            self.setWindowTitle(self.windowTitle() + " ")
            self.setWindowTitle(self.windowTitle().rstrip())
        except Exception as e:
            self._log_silent("Перекраска заголовка окна", e)

    def _apply_titlebar_theme_to_widget(self, widget):
        """Перекрашивает заголовок указанного окна/диалога."""

        if os.name != 'nt':
            return
        try:
            hwnd = int(widget.winId())
            dark = self.settings.get("theme", "light") == "dark"
            value = ctypes.c_int(1 if dark else 0)
            for attr in (20, 19):
                ctypes.windll.dwmapi.DwmSetWindowAttribute(
                    hwnd, attr,
                    ctypes.byref(value),
                    ctypes.sizeof(value)
                )
            # Форсируем перерисовку заголовка
            widget.setWindowTitle(widget.windowTitle() + " ")
            widget.setWindowTitle(widget.windowTitle().rstrip())
        except Exception as e:
            self._log_silent("Перекраска заголовка диалога", e)

    def _show_pending_load_errors(self):
        errors = getattr(self, '_pending_errors', None)
        if not errors:
            return
        self._pending_errors = None
        msg = "\n".join(errors[:10])
        if len(errors) > 10:
            msg += f"\n…и ещё {len(errors) - 10}"
        QMessageBox.warning(
            self,
            "Часть чатов не загружена",
            f"Повреждённые файлы перемещены в папку 'corrupted':\n\n{msg}\n\n"
            "Ты можешь попробовать восстановить их из папки 'backups' вручную."
        )

    def refresh_unread_ui(self):
        """Обновляет заголовок окна и иконку в панели задач на основе количества непрочитанных чатов."""

        count = len(self.unread_chats)

        # === Заголовок окна ===
        base_title = "Echos"
        if count > 0:
            self.setWindowTitle(f"{base_title} ({count})")
        else:
            self.setWindowTitle(base_title)

        # === Иконка в панели задач (Windows) ===
        self.update_taskbar_icon()

    @contextmanager
    def busy(self, text="Загрузка…"):
        """Показывает оверлей на время выполнения блока."""

        self.busy_overlay.show_overlay(self, text)
        QApplication.processEvents()
        try:
            yield
        finally:
            self.busy_overlay.hide_overlay()

    def update_taskbar_icon(self):
        """Рисует иконку окна с числом непрочитанных (красный кружок в углу)."""

        from PySide6.QtGui import QPainter, QColor, QFont

        # Путь к базовой иконке — определяем СНАЧАЛА
        icon_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "Icon/Icon.ico")
        base_icon = QIcon(icon_path)

        # Если непрочитанных нет — принудительно сбрасываем иконку
        if not self.unread_chats:
            try:
                # 1. Пустая иконка — сбрасывает состояние Windows
                self.setWindowIcon(QIcon())
                QApplication.processEvents()

                # 2. Чистая иконка
                self.setWindowIcon(base_icon)
                QApplication.processEvents()

                # 3. ТРЮК: временно меняем заголовок окна.
                #    Windows перечитывает иконку при смене заголовка.
                old_title = self.windowTitle()
                self.setWindowTitle(old_title + " ")
                QTimer.singleShot(10, lambda t=old_title: self.setWindowTitle(t))

                # 4. Дублируем установку иконки с задержкой — на случай,
                #    если Windows не успела обработать смену заголовка.
                QTimer.singleShot(50, lambda ic=base_icon: self.setWindowIcon(ic))
            except Exception as e:
                print(f"[Taskbar] Не удалось сбросить иконку: {e}")
            return

        if base_icon.isNull():
            return

        size = 64
        pixmap = base_icon.pixmap(size, size)
        if pixmap.isNull():
            return

        count = len(self.unread_chats)
        if count == 0:
            self.setWindowIcon(QIcon())
            self.setWindowIcon(base_icon)
            return

        painter = QPainter(pixmap)
        painter.setRenderHint(QPainter.Antialiasing)

        # Красный кружок в правом верхнем углу
        badge_size = 26
        x = size - badge_size
        y = 0
        painter.setBrush(QColor("#d32f2f"))
        painter.setPen(Qt.NoPen)
        painter.drawEllipse(x, y, badge_size, badge_size)

        # Цифра внутри кружка
        painter.setPen(QColor("white"))
        font = QFont()
        font.setBold(True)
        font.setPixelSize(18)
        painter.setFont(font)
        text = str(count) if count < 100 else "99+"
        painter.drawText(x, y, badge_size, badge_size, Qt.AlignCenter, text)
        painter.end()

        new_icon = QIcon(pixmap)
        self.setWindowIcon(QIcon())          # сброс кэша Windows
        self.setWindowIcon(new_icon)

    def render_dot_to_pixmap(self, dot_code: str) -> QPixmap:
        """Рендерит DOT-код в изображение с помощью Graphviz."""

        if not GRAPHVIZ_AVAILABLE:
            return QPixmap()
        try:
            src = graphviz.Source(dot_code)
            # Рендерим во временный PNG-файл
            output_path = src.render(filename='temp_scheme', format='png', cleanup=True)
            pixmap = QPixmap(output_path)
            if not pixmap.isNull():
                return pixmap
            return QPixmap()
        except Exception as e:
            self.logger.warning(f"Ошибка рендеринга DOT: {e}")
            return QPixmap()

    def show_diagram_from_text(self, text: str, python_code: str = ""):
        """Строит схему: сначала пытается использовать Python-код, затем DOT, затем простые стрелки."""

        if not GRAPHVIZ_AVAILABLE:
            QMessageBox.warning(
                self, "Graphviz не установлен",
                "Для отображения схем установите Graphviz:\nhttps://graphviz.org/download/\n"
                "И добавьте его в системный PATH."
            )
            return

        # 1. Если передан Python-код — строим схему из него
        if python_code:
            dot_code = self.python_code_to_dot(python_code)
            if dot_code:
                pixmap = self.render_dot_to_pixmap(dot_code)
                if not pixmap.isNull():
                    dialog = SchemeViewerDialog(pixmap, self)
                    dialog.exec()
                    return

        # 2. Пытаемся извлечь DOT-блок из текста
        dot_blocks = re.findall(r'```dot\s+(.*?)```', text, re.DOTALL)
        if dot_blocks:
            dot_code = dot_blocks[0].strip()
            pixmap = self.render_dot_to_pixmap(dot_code)
            if not pixmap.isNull():
                dialog = SchemeViewerDialog(pixmap, self)
                dialog.exec()
                return

        # 3. Если DOT нет — пытаемся извлечь рёбра из простого текста и сформировать DOT
        edges = self._extract_edges_from_text(text)
        if edges:
            nodes = set()
            for src, dst in edges:
                nodes.add(src)
                nodes.add(dst)
            dot_lines = ['digraph G {']
            for node in nodes:
                shape = self._classify_shape(node)
                dot_lines.append(f'  "{node}" [shape={shape}]')
            for src, dst in edges:
                dot_lines.append(f'  "{src}" -> "{dst}"')
            dot_lines.append('}')
            dot_code = '\n'.join(dot_lines)
            pixmap = self.render_dot_to_pixmap(dot_code)
            if not pixmap.isNull():
                dialog = SchemeViewerDialog(pixmap, self)
                dialog.exec()
                return

        QMessageBox.information(self, "Схема", "Не удалось построить схему из данного сообщения.")

    def _extract_edges_from_text(self, text):
        """Извлекает рёбра из произвольного текста (поддерживает разные стрелки)."""

        edges = []
        # Варианты стрелок: ->, →, –>, —>, -->
        pattern = re.compile(r'(?P<src>\w+|\"[^\"]+\")\s*(?:->|→|–>|—>|-->)\s*(?P<dst>\w+|\"[^\"]+\")')
        for m in pattern.finditer(text):
            src = m.group('src').strip('"')
            dst = m.group('dst').strip('"')
            edges.append((src, dst))
        return edges

    def python_code_to_dot(self, code_text: str) -> str:
        """Преобразует Python-код в DOT-граф блок-схемы."""

        import ast
        import re

        def make_id():
            make_id.counter += 1
            return f"n{make_id.counter}"

        make_id.counter = 0

        nodes = []  # список кортежей (id, label, shape)
        edges = []  # список кортежей (src_id, dst_id)

        def add_node(label, shape):
            nid = make_id()
            nodes.append((nid, label, shape))
            return nid

        def add_edge(src, dst):
            if src is not None and dst is not None:
                edges.append((src, dst))

        def process_body(body, prev_id):
            """Обрабатывает список операторов. Возвращает последний активный узел."""

            current = prev_id
            for stmt in body:
                if isinstance(stmt, ast.Assign):
                    # Проверяем, есть ли справа вызов input()
                    if isinstance(stmt.value, ast.Call) and isinstance(stmt.value.func,
                                                                       ast.Name) and stmt.value.func.id == 'input':
                        prompt = ast.unparse(stmt.value.args[0]) if stmt.value.args else ""
                        target = ast.unparse(stmt.targets[0])
                        nid = add_node(f"Ввод {target}: {prompt}", "parallelogram")
                    else:
                        targets = ", ".join([ast.unparse(t) for t in stmt.targets])
                        value = ast.unparse(stmt.value)
                        nid = add_node(f"{targets} = {value}", "box")
                    add_edge(current, nid)
                    current = nid
                elif isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
                    func = stmt.value.func
                    if isinstance(func, ast.Name):
                        if func.id == 'input':
                            prompt = ast.unparse(stmt.value.args[0]) if stmt.value.args else ""
                            nid = add_node(f"Ввод {prompt}", "parallelogram")
                            add_edge(current, nid)
                            current = nid
                        elif func.id == 'print':
                            args = ", ".join([ast.unparse(a) for a in stmt.value.args])
                            nid = add_node(f"Вывод {args}", "parallelogram")
                            add_edge(current, nid)
                            current = nid
                        # Другие вызовы игнорируем
                elif isinstance(stmt, ast.If):
                    current = self._process_if(stmt, current, add_node, add_edge, process_body)
                elif isinstance(stmt, ast.While):
                    cond_id = add_node(f"Цикл: {ast.unparse(stmt.test)}", "diamond")
                    add_edge(current, cond_id)
                    body_end = process_body(stmt.body, cond_id)
                    add_edge(body_end, cond_id)  # обратная связь
                    # Точка выхода из цикла
                    exit_id = add_node("", "point")
                    add_edge(cond_id, exit_id)
                    current = exit_id
                elif isinstance(stmt, ast.For):
                    target = ast.unparse(stmt.target)
                    iter_ = ast.unparse(stmt.iter)
                    cond_id = add_node(f"Для {target} в {iter_}", "diamond")
                    add_edge(current, cond_id)
                    body_end = process_body(stmt.body, cond_id)
                    add_edge(body_end, cond_id)
                    exit_id = add_node("", "point")
                    add_edge(cond_id, exit_id)
                    current = exit_id
                # Остальные конструкции (return, break и т.д.) можно добавить
                elif isinstance(stmt, ast.Return):
                    nid = add_node(f"Возврат {ast.unparse(stmt.value) if stmt.value else ''}", "box")
                    add_edge(current, nid)
                    current = nid
                elif isinstance(stmt, ast.Break):
                    nid = add_node("Прервать", "box")
                    add_edge(current, nid)
                    current = nid
                elif isinstance(stmt, ast.Continue):
                    nid = add_node("Продолжить", "box")
                    add_edge(current, nid)
                    current = nid
                else:
                    # Необработанные конструкции пропускаем
                    pass
            return current

        try:
            tree = ast.parse(code_text)
        except SyntaxError:
            return ""

        start_id = add_node("Начало", "ellipse")
        end_id = add_node("Конец", "ellipse")
        last_id = process_body(tree.body, start_id)
        add_edge(last_id, end_id)

        dot_lines = ["digraph G {"]
        for nid, label, shape in nodes:
            label_escaped = label.replace('"', '\\"')
            if shape == "point":
                dot_lines.append(f'  "{nid}" [shape=point, width=0.1, height=0.1, label=""];')
            else:
                dot_lines.append(f'  "{nid}" [shape={shape}, label="{label_escaped}"];')
        for src, dst in edges:
            dot_lines.append(f'  "{src}" -> "{dst}";')
        dot_lines.append("}")
        return "\n".join(dot_lines)

    def _process_if(self, if_stmt, prev_id, add_node, add_edge, process_body):
        """Обрабатывает if/elif/else, возвращает точку слияния."""

        # Создаём узел условия
        cond_id = add_node(f"Если {ast.unparse(if_stmt.test)}", "diamond")
        add_edge(prev_id, cond_id)

        # Обрабатываем основную ветку
        true_end = process_body(if_stmt.body, cond_id)

        # Если есть else/elif
        if if_stmt.orelse:
            # Если это elif
            if len(if_stmt.orelse) == 1 and isinstance(if_stmt.orelse[0], ast.If):
                # Рекурсивно обрабатываем elif, начиная с того же условия (cond_id)
                # но cond_id уже использован, нужно создать новую точку слияния позже
                elif_end = self._process_if(if_stmt.orelse[0], cond_id, add_node, add_edge, process_body)
                # Создаём точку слияния
                merge_id = add_node("", "point")
                add_edge(true_end, merge_id)
                add_edge(elif_end, merge_id)
                return merge_id
            else:
                # Обычный else
                false_end = process_body(if_stmt.orelse, cond_id)
                merge_id = add_node("", "point")
                add_edge(true_end, merge_id)
                add_edge(false_end, merge_id)
                return merge_id
        else:
            # Нет else – точка слияния всё равно нужна для выхода
            merge_id = add_node("", "point")
            add_edge(true_end, merge_id)
            return merge_id

    def extract_python_code_from_message(self, content: str) -> str:
        """Извлекает Python-код из блока ```python ... ``` или возвращает весь текст, если это код."""

        # Ищем блок python
        blocks = re.findall(r'```python\s+(.*?)```', content, re.DOTALL)
        if blocks:
            return blocks[0]
        # Если блока нет, но текст выглядит как код (содержит def, import, print и т.п.)
        # Простая эвристика: много строк с отступами и ключевыми словами
        lines = content.strip().splitlines()
        if len(lines) > 1 and any(
                line.strip().startswith(('import ', 'from ', 'def ', 'if ', 'for ', 'while ', 'print(', 'input('))
                for line in lines
        ):
            return content
        return ""

    def _classify_shape(self, node_text):
        """Определяет форму узла по его содержимому."""
        t = node_text.lower()
        if any(word in t for word in ['начало', 'конец', 'start', 'end', 'начать', 'завершить']):
            return 'ellipse'
        if any(word in t for word in ['ввод', 'вывод', 'input', 'output', 'вход', 'выход']):
            return 'parallelogram'
        if any(word in t for word in ['если', 'if', 'условие', '?', 'condition', 'проверка']):
            return 'diamond'
        # По умолчанию – прямоугольник
        return 'box'

    def _install_excepthook(self):
        """Логирует необработанные исключения — чтобы они попадали в app.log,
        а значит были видны в консоли отладки."""
        import traceback

        def handler(exc_type, exc_value, exc_tb):
            tb_text = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
            try:
                self.logger.critical(
                    "Необработанное исключение:\n%s", tb_text
                )
            except Exception:
                pass

            # Пробуем показать пользователю MessageBox, если есть QApplication
            try:
                from PySide6.QtWidgets import QApplication, QMessageBox
                if QApplication.instance() is not None:
                    msg = QMessageBox()
                    msg.setIcon(QMessageBox.Critical)
                    msg.setWindowTitle("Критическая ошибка")
                    msg.setText("Произошла непредвиденная ошибка.")
                    msg.setDetailedText(tb_text)
                    msg.exec()
            except Exception:
                pass

        sys.excepthook = handler

    def setup_logging(self):
        log_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "logs")
        os.makedirs(log_dir, exist_ok=True)
        log_file = os.path.join(log_dir, "app.log")

        import logging
        from logging.handlers import RotatingFileHandler

        handler = RotatingFileHandler(
            log_file,
            maxBytes=2 * 1024 * 1024,
            backupCount=3,
            encoding='utf-8'
        )
        handler.setFormatter(logging.Formatter(
            '%(asctime)s - %(levelname)s - %(name)s - %(message)s'
        ))

        # Настраиваем корневой логгер — тогда ВСЕ модульные логгеры
        # (logging.getLogger(__name__)) будут писать в тот же файл.
        root = logging.getLogger()
        root.setLevel(logging.INFO)
        root.handlers.clear()
        root.addHandler(handler)

        # Оставляем self.logger для совместимости со старым кодом,
        # но теперь он пишет туда же, куда и корневой.
        self.logger = logging.getLogger("ChatApp")

    def _log_silent(self, action: str, exc: Exception = None):
        """Тихое логирование для мест, где ошибка не критична для пользователя.

        Используется вместо `except Exception: pass` в фоновых операциях.
        Пользователь ничего не видит, но в logs/app.log попадает след.

        Пример:
            try:
                os.remove(path)
            except Exception as e:
                self._log_silent(f"Не удалось удалить {path}", e)
        """

        try:
            msg = f"[silent] {action}"
            if exc is not None:
                msg += f" — {type(exc).__name__}: {exc}"
            if self.logger:
                self.logger.warning(msg)
        except Exception:
            # Если даже логгер не работает — молчим.
            pass

    def _collect_bug_report_info(self, exc_type=None, exc_value=None, exc_tb=None):
        """Собирает информацию для баг-репорта."""

        import platform
        from datetime import datetime

        info_lines = []
        info_lines.append(f"- **Версия Echos:** {APP_VERSION}")

        os_name = platform.system()
        os_ver = platform.release()
        if os_name == 'Windows':
            os_ver = f"Windows {platform.version()}"
        info_lines.append(f"- **ОС:** {os_name} {os_ver}")
        info_lines.append(f"- **Python:** {platform.python_version()}")

        try:
            import PySide6
            info_lines.append(f"- **PySide6:** {PySide6.__version__}")
        except Exception:
            pass

        provider = self.settings.get("llm_provider", "?")
        info_lines.append(f"- **Провайдер LLM:** {provider}")

        if 0 <= self.current_chat_index < len(self.chats):
            model = self.chats[self.current_chat_index].get('model', '?')
            info_lines.append(f"- **Модель:** {model}")

        info_lines.append(f"- **Дата:** {datetime.now().strftime('%d.%m.%Y %H:%M:%S')}")

        # Последние 100 строк лога
        log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "logs", "app.log")
        log_excerpt = "(лог недоступен)"
        if os.path.exists(log_path):
            try:
                with open(log_path, 'r', encoding='utf-8', errors='ignore') as f:
                    lines = f.readlines()
                    log_excerpt = "".join(lines[-100:])
            except Exception:
                pass

        # Трассировка
        traceback_text = ""
        if exc_type is not None:
            import traceback as _tb
            traceback_text = "".join(_tb.format_exception(exc_type, exc_value, exc_tb))

        # Формируем тело
        body_parts = []
        body_parts.append("**Описание проблемы:**")
        body_parts.append("_(опишите, что вы делали, когда возникла ошибка)_")
        body_parts.append("")
        body_parts.append("**Шаги для воспроизведения:**")
        body_parts.append("1. ")
        body_parts.append("2. ")
        body_parts.append("3. ")
        body_parts.append("")
        body_parts.append("**Ожидаемое поведение:**")
        body_parts.append("_(что должно было произойти)_")
        body_parts.append("")
        body_parts.append("**Фактическое поведение:**")
        body_parts.append("_(что произошло на самом деле)_")
        body_parts.append("")
        body_parts.append("---")
        body_parts.append("")
        body_parts.append("## Системная информация")
        body_parts.append("")
        body_parts.extend(info_lines)
        body_parts.append("")

        if traceback_text:
            body_parts.append("## Трассировка ошибки")
            body_parts.append("")
            body_parts.append("```")
            body_parts.append(traceback_text[:3000])
            body_parts.append("```")
            body_parts.append("")

        body_parts.append("## Лог (последние 100 строк)")
        body_parts.append("")
        body_parts.append("```")
        body_parts.append(log_excerpt[:5000])
        body_parts.append("```")

        title = "[BUG] "
        if exc_type:
            title += f"{exc_type.__name__}: "
            if exc_value:
                title += str(exc_value)[:60]

        return {
            "title": title,
            "body": "\n".join(body_parts),
        }

    def send_bug_report(self, exc_type=None, exc_value=None, exc_tb=None):
        """Открывает GitHub Issues с предзаполненной формой."""

        info = self._collect_bug_report_info(exc_type, exc_value, exc_tb)

        # Копируем в буфер обмена
        full_text = f"{info['title']}\n\n{info['body']}"
        QApplication.clipboard().setText(full_text)

        from urllib.parse import quote
        title_enc = quote(info["title"])
        body_enc = quote(info["body"])

        # Проверяем, что GITHUB_REPO настроен
        if GITHUB_REPO == "#/#" or not GITHUB_REPO:
            QMessageBox.information(
                self, "Баг-репорт",
                "Текст баг-репорта скопирован в буфер обмена.\n\n"
                "Откройте страницу проекта и создайте Issue вручную."
            )
            QDesktopServices.openUrl(QUrl("https://github.com/Vecsai/Echos/issues/new"))
            return

        url = (f"https://github.com/{GITHUB_REPO}/issues/new"
               f"?title={title_enc}&body={body_enc}&labels=bug")
        QDesktopServices.openUrl(QUrl(url))

        self.statusBar().showMessage(
            "Текст баг-репорта скопирован в буфер обмена", 5000
        )

    def load_settings(self):
        """Загружает конфиг и прогоняет миграции к актуальной версии."""
        if not os.path.exists(self.config_file):
            # Первый запуск — пишем дефолты с текущей версией
            self.settings["config_version"] = CONFIG_VERSION
            self.save_settings()
            return

        data = self._safe_json_load(self.config_file, None)
        if not isinstance(data, dict):
            self.logger.warning(
                "chat_config.json повреждён или имеет неверный формат. "
                "Использую дефолтные настройки."
            )
            self.settings = copy.deepcopy(self.DEFAULT_SETTINGS)
            self.settings["config_version"] = CONFIG_VERSION
            self.save_settings()
            return

        # Мигрируем и мерджим с дефолтами
        migrated = self._migrate_settings(data)

        self.settings.update(migrated)
        self.settings["config_version"] = CONFIG_VERSION

        # Устаревший ключ — убираем
        if "encryption_key" in self.settings:
            del self.settings["encryption_key"]

        # Проверяем наличие всех ключей горячих клавиш
        default_hotkeys = self.DEFAULT_SETTINGS["hotkeys"]
        if "hotkeys" not in self.settings or not isinstance(self.settings["hotkeys"], dict):
            self.settings["hotkeys"] = {}
        for key, value in default_hotkeys.items():
            if key not in self.settings["hotkeys"]:
                self.settings["hotkeys"][key] = value

        # Сохраняем (уже с актуальной версией и дополненными ключами)
        self.save_settings()

    def save_settings(self):
        try:
            # Гарантируем актуальную версию перед записью
            self.settings["config_version"] = CONFIG_VERSION

            with open(self.config_file, 'w', encoding='utf-8') as f:
                json.dump(self.settings, f, ensure_ascii=False, indent=2)

            api = PluginAPI(self)
            for plugin in self.plugins:
                try:
                    if hasattr(plugin, 'on_settings_changed'):
                        plugin.on_settings_changed(self.settings, api)
                except Exception as e:
                    self.logger.warning(f"Ошибка в on_settings_changed: {e}")
        except Exception as e:
            self.logger.error(f"Ошибка сохранения настроек: {e}")
            self.show_error(
                "Ошибка сохранения",
                f"Не удалось сохранить настройки.\nПричина: {e}"
            )

    def load_folders(self) -> List[Dict[str, Any]]:
        if os.path.exists(self.folders_file):
            try:
                with open(self.folders_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, list):
                    return [{"name": str(name), "color": "#FFFFFF", "pinned": False} for name in data]
                elif isinstance(data, dict) and 'folders' in data:
                    result = []
                    for folder in data['folders']:
                        if isinstance(folder, dict):
                            result.append(folder)
                        else:
                            result.append({"name": str(folder), "color": "#FFFFFF", "pinned": False})
                    return result
            except (json.JSONDecodeError, UnicodeDecodeError) as e:
                self.logger.warning(f"Ошибка загрузки папок: {e}. Создаю пустой список.")
            except Exception as e:
                self.logger.warning(f"Неизвестная ошибка при чтении папок: {e}. Создаю пустой список.")
        return []

    def save_folders(self):
        try:
            with open(self.folders_file, 'w', encoding='utf-8') as f:
                json.dump({"folders": self.folders}, f, ensure_ascii=False, indent=2)
        except Exception as e:
            self.logger.error(f"Ошибка сохранения папок: {e}")
            self.show_error("Ошибка сохранения", f"Не удалось сохранить папки.\nПричина: {e}")

    def load_trash(self):
        if os.path.exists('trash.json'):
            data = self._safe_json_load('trash.json', [])
            if isinstance(data, list):
                self.trash_items = data
                self.deduplicate_trash()
                return self.trash_items
            else:
                self.logger.warning("trash.json повреждён, корзина пуста.")
                return []
        return []

    def save_trash(self):
        self.deduplicate_trash()
        try:
            with open('trash.json', 'w', encoding='utf-8') as f:
                json.dump(self.trash_items, f, ensure_ascii=False, indent=2)
        except Exception as e:
            self.logger.error(f"Ошибка сохранения корзины: {e}")
            self.show_error("Ошибка сохранения", f"Не удалось сохранить корзину.\nПричина: {e}")

    def load_prompts(self):
        if os.path.exists('prompts.json'):
            data = self._safe_json_load('prompts.json', [])
            if isinstance(data, list):
                return data
            else:
                self.logger.warning("prompts.json повреждён, список промптов пуст.")
                return []
        return []

    def save_prompts(self):
        """Сохраняет промпты в файл prompts.json."""

        try:
            with open('prompts.json', 'w', encoding='utf-8') as f:
                json.dump(self.prompts, f, ensure_ascii=False, indent=2)
        except Exception as e:
            self.logger.error(f"Ошибка сохранения промптов: {e}")
            self.show_error("Ошибка сохранения", f"Не удалось сохранить промпты.\nПричина: {e}")

    def load_last_chat_filepath(self):
        if os.path.exists("last_session.json"):
            data = self._safe_json_load("last_session.json", None)
            if isinstance(data, dict):
                return data.get("last_chat")
        return None

    def save_last_chat_filepath(self):
        """Сохраняет путь к последнему активному чату."""

        if self.current_chat_index >= 0 and self.current_chat_index < len(self.chats):
            filepath = self.chats[self.current_chat_index]['filepath']
            try:
                with open("last_session.json", 'w', encoding='utf-8') as f:
                    json.dump({"last_chat": filepath}, f)
            except Exception as e:
                self.logger.warning(f"Не удалось сохранить last_session: {e}")

    def load_scroll_positions(self):
        """Загружает позиции скролла из файла."""
        if not os.path.exists(self.scroll_positions_file):
            return
        try:
            with open(self.scroll_positions_file, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if not isinstance(data, dict):
                return
            # Новый формат — два словаря
            if "msg_idx" in data and isinstance(data["msg_idx"], dict):
                self.chat_scroll_positions_msg_idx = data["msg_idx"]
            if "ratio" in data and isinstance(data["ratio"], dict):
                self.chat_scroll_positions = data["ratio"]
        except Exception as e:
            self.logger.warning(f"Не удалось загрузить позиции скролла: {e}")

    def save_scroll_positions(self):
        """Сохраняет позиции скролла в файл."""
        try:
            data = {
                "ratio": self.chat_scroll_positions,
                "msg_idx": self.chat_scroll_positions_msg_idx,
            }
            with open(self.scroll_positions_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
        except Exception as e:
            self.logger.warning(f"Не удалось сохранить позиции скролла: {e}")

    def load_cursor_positions(self):
        if os.path.exists("cursor_positions.json"):
            try:
                with open("cursor_positions.json", 'r', encoding='utf-8') as f:
                    data = json.load(f)
                if isinstance(data, dict):
                    return data
            except Exception as e:
                self.logger.warning(f"Не удалось загрузить позиции курсора: {e}")
        return {}

    def save_cursor_positions(self):
        try:
            with open("cursor_positions.json", 'w', encoding='utf-8') as f:
                json.dump(self.chat_cursor_positions, f, ensure_ascii=False, indent=2)
        except Exception as e:
            self.logger.warning(f"Не удалось сохранить позиции курсора: {e}")

    def resource_path(self, relative_path):
        if hasattr(sys, '_MEIPASS'):
            return os.path.join(sys._MEIPASS, relative_path)
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), relative_path)

    def _safe_json_load(self, filepath, default):
        """Безопасно загружает JSON. Если файл повреждён, возвращает default."""

        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                return json.load(f)
        except (json.JSONDecodeError, UnicodeDecodeError, FileNotFoundError) as e:
            self.logger.warning(f"Ошибка загрузки {filepath}: {e}. Использую значение по умолчанию.")
            return default
        except Exception as e:
            self.logger.warning(f"Неизвестная ошибка при чтении {filepath}: {e}. Использую значение по умолчанию.")
            return default

    def deduplicate_trash(self):
        """Удаляет дубликаты записей в корзине по ключу (filepath для чатов, name для папок)."""

        seen_chat = set()
        seen_folder = set()
        unique = []
        for entry in self.trash_items:
            if entry.get('type') == 'chat':
                key = entry.get('filepath')
                if key and key not in seen_chat:
                    seen_chat.add(key)
                    unique.append(entry)
            elif entry.get('type') == 'folder':
                key = entry.get('name')
                if key and key not in seen_folder:
                    seen_folder.add(key)
                    unique.append(entry)
            else:
                # Неизвестный тип – оставляем как есть
                unique.append(entry)
        self.trash_items = unique

    def _hash_password(self, password: str) -> str:
        return hashlib.sha256(password.encode('utf-8')).hexdigest()

    def format_chat_title(self, chat):
        return chat.get('title', '')

    def update_chat_item_text(self, chat):
        filepath = chat['filepath']
        item = self.chat_items.get(filepath)
        if not item:
            return

        title = chat.get('title', '')
        prefix = ""
        if chat.get('incognito', False):
            prefix += "🕶 "

        # Иконка чата — обычная, без подмены
        dark = self.settings.get("theme", "light") == "dark"
        item.setIcon(0, self.icon_chat_white if dark else self.icon_chat)
        item.setText(0, prefix + title)

        # Тултип — с инфо о родителе, если это ветка
        if chat.get('parent_filepath'):
            parent_title = chat.get('parent_title', '?')
            fork_idx = chat.get('fork_from_idx', '?')
            item.setToolTip(
                0,
                f"Ветка от чата «{parent_title}»\n"
                f"Точка ветвления: сообщение #{fork_idx + 1}\n\n"
                f"ПКМ → «Перейти к оригиналу»"
            )
        else:
            item.setToolTip(0, "")

        # Колонка 2 — теги
        tags = chat.get('tags', [])
        if tags:
            tags_str = ' '.join(['#' + tag for tag in tags])
            item.setText(2, tags_str)
            item.setForeground(2, QBrush(QColor("#1a73e8")))
        else:
            item.setText(2, "")

        # Форсируем перерисовку через делегат
        self.chat_tree.update()
        self.chat_tree.viewport().update()

    def edit_chat_tags(self, filepath):
        idx = self.find_chat_index(filepath)
        if idx < 0:
            return
        chat = self.chats[idx]
        dialog = TagsDialog(self.settings.get("all_tags", []), chat.get('tags', []), self)
        result = dialog.exec()
        # Всегда сохраняем глобальный список тегов (в нём могут быть теги, не привязанные к чатам)
        self.settings["all_tags"] = dialog.get_all_tags()
        self.save_settings()
        # Применяем изменения к чату только если окно закрыто через "Выбрать" или "Сбросить"
        if result == QDialog.Accepted:
            chat['tags'] = list(dialog.get_current_tags())
            self.save_chat_by_filepath(filepath)
            self.update_chat_item_text(chat)
            self.statusBar().showMessage("Теги обновлены")

    def remove_chat_tag(self, filepath, tag):
        idx = self.find_chat_index(filepath)
        if idx < 0:
            return
        chat = self.chats[idx]
        tags = chat.get('tags', [])
        if tag in tags:
            tags.remove(tag)
            chat['tags'] = tags
            self.save_chat_by_filepath(filepath)
            self.update_chat_item_text(chat)
            self.statusBar().showMessage(f"Тег '#{tag}' удалён")

    def save_draft(self, text: str):
        """Сохраняет черновик в файл draft.txt."""

        try:
            with open("draft.txt", "w", encoding="utf-8") as f:
                f.write(text)
        except Exception as e:
            self._log_silent("Сохранение черновика", e)

    def _on_draft_changed(self):
        """Сбрасывает таймер автосохранения при каждом изменении текста."""

        if hasattr(self, '_draft_save_timer'):
            self._draft_save_timer.start()

    def _save_draft_now(self):
        """Сохраняет текущий черновик в файл."""

        try:
            text = self.input_edit.toPlainText()
            self.save_draft(text)
        except Exception as e:
            self._log_silent("Автосохранение черновика", e)

    def load_draft(self) -> str:
        """Загружает черновик из файла draft.txt. Если файла нет, возвращает пустую строку."""

        if os.path.exists("draft.txt"):
            try:
                with open("draft.txt", "r", encoding="utf-8") as f:
                    return f.read()
            except Exception as e:
                self._log_silent("Чтение черновика", e)
        return ""

    def restore_draft(self):
        """Восстанавливает черновик в поле ввода."""

        draft = self.load_draft()
        if draft.strip():
            self.input_edit.setPlainText(draft)
            self.statusBar().showMessage("Восстановлен неотправленный черновик")

