    def attach_files(self):
        # Создаём экземпляр диалога вместо использования статического метода
        dlg = QFileDialog(self, "Выберите файлы", "")
        dlg.setOption(QFileDialog.DontUseNativeDialog, True)  # Важно для отображения кастомных иконок в Windows
        dlg.setWindowIcon(QIcon(self.resource_path("Image/Attach_dialog.png")))
        dlg.setFileMode(QFileDialog.ExistingFiles)  # Позволяет выбирать несколько файлов
        dlg.setNameFilters([
            "Все поддерживаемые (*.txt *.md *.py *.json *.csv *.html *.log *.pdf *.docx *.pptx *.png *.jpg *.jpeg *.gif *.bmp *.webp)",
            "Текстовые (*.txt *.md *.py *.json *.csv *.html *.log)",
            "Документы (*.pdf *.docx *.pptx)",
            "Изображения (*.png *.jpg *.jpeg *.gif *.bmp *.webp)",
            "Все файлы (*)"
        ])

        # Открываем диалог и проверяем, нажал ли пользователь "Открыть"
        if not dlg.exec():
            return

        file_paths = dlg.selectedFiles()
        if not file_paths:
            return

        for path in file_paths:
            self.attachments.append(path)
        self.update_attachments_ui()

    def update_attachments_ui(self):
        # Очищаем layout
        while self.attachments_layout.count():
            item = self.attachments_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        # Выравниваем по левому краю
        self.attachments_layout.setAlignment(Qt.AlignLeft)

        # Для каждого прикреплённого файла создаём компактный контейнер
        for path in self.attachments:
            container = QWidget()
            container.setStyleSheet("""
                QWidget {
                    background-color: #FCE4EC;  /* светло-розовый */
                    border-radius: 8px;
                }
            """)
            container_layout = QHBoxLayout(container)
            container_layout.setContentsMargins(4, 2, 4, 2)
            container_layout.setSpacing(2)

            # Обрезаем длинное имя файла
            name = os.path.basename(path)
            if len(name) > 20:
                name = name[:17] + "..."
            label = QLabel(name)
            label.setToolTip(path)
            label.setStyleSheet("background: transparent; border: none; font-size: 12px; color: #333;")

            # Маленькая круглая кнопка удаления
            btn_remove = QPushButton()
            btn_remove.setIcon(self.icon_close)
            btn_remove.setIconSize(QSize(12, 12))
            btn_remove.setFixedSize(16, 16)
            btn_remove.setStyleSheet("""
                QPushButton {
                    border-radius: 8px;
                    background-color: #D32F2F;
                    border: none;
                }
                QPushButton:hover {
                    background-color: #B71C1C;
                }
            """)
            btn_remove.clicked.connect(lambda checked, p=path: self.remove_attachment(p))

            container_layout.addWidget(label)
            container_layout.addWidget(btn_remove)

            # Фиксированная ширина контейнера
            container.setFixedWidth(150)

            self.attachments_layout.addWidget(container)

        # Растяжка, чтобы элементы прижимались влево
        self.attachments_layout.addStretch(1)

        # Показываем/скрываем область прокрутки
        self.attachments_scroll.setVisible(bool(self.attachments))

    def remove_attachment(self, path):
        """Удаляет прикреплённый файл из списка."""

        if path in self.attachments:
            self.attachments.remove(path)
            self.update_attachments_ui()

    @staticmethod
    def _table_to_markdown(table: list) -> str:
        """Преобразует таблицу (список строк) в Markdown-формат."""

        if not table:
            return ""
        # Очищаем ячейки
        rows = []
        for row in table:
            if not row:
                continue
            cells = [str(c).strip() if c is not None else "" for c in row]
            if any(cells):
                rows.append(cells)
        if not rows:
            return ""

        # Выравниваем длину строк
        max_cols = max(len(r) for r in rows)
        rows = [r + [""] * (max_cols - len(r)) for r in rows]

        header = rows[0]
        body = rows[1:]

        lines = ["| " + " | ".join(header) + " |"]
        lines.append("| " + " | ".join(["---"] * max_cols) + " |")
        for r in body:
            lines.append("| " + " | ".join(r) + " |")
        return "\n".join(lines)

    def extract_tables_from_file(self, path: str) -> list:
        """Извлекает таблицы из PDF/DOCX/PPTX. Возвращает список Markdown-строк."""

        ext = os.path.splitext(path)[1].lower()
        tables_md = []

        try:
            # === DOCX ===
            if ext == '.docx' and DOCX_AVAILABLE:
                doc = Document(path)
                for i, table in enumerate(doc.tables, 1):
                    rows = []
                    for row in table.rows:
                        cells = [cell.text.strip() for cell in row.cells]
                        rows.append(cells)
                    md = self._table_to_markdown(rows)
                    if md:
                        tables_md.append(f"**Таблица {i}:**\n\n{md}")

            # === PDF ===
            elif ext == '.pdf' and PDFPLUMBER_AVAILABLE:
                with pdfplumber.open(path) as pdf:
                    for page_num, page in enumerate(pdf.pages, 1):
                        try:
                            page_tables = page.extract_tables()
                        except Exception:
                            continue
                        for t_idx, table in enumerate(page_tables, 1):
                            md = self._table_to_markdown(table)
                            if md:
                                label = f"**Таблица (стр. {page_num}"
                                if len(page_tables) > 1:
                                    label += f", №{t_idx}"
                                label += "):**"
                                tables_md.append(f"{label}\n\n{md}")

            # === PPTX ===
            elif ext == '.pptx' and PPTX_AVAILABLE:
                prs = Presentation(path)
                for slide_num, slide in enumerate(prs.slides, 1):
                    for shape in slide.shapes:
                        if shape.has_table:
                            rows = []
                            for row in shape.table.rows:
                                cells = [cell.text.strip() for cell in row.cells]
                                rows.append(cells)
                            md = self._table_to_markdown(rows)
                            if md:
                                tables_md.append(f"**Таблица (слайд {slide_num}):**\n\n{md}")
        except Exception as e:
            self.logger.warning(f"Ошибка извлечения таблиц из {path}: {e}")

        return tables_md

    def read_file_content(self, path):
        ext = os.path.splitext(path)[1].lower()
        text = ""
        try:
            if ext in ('.txt', '.md', '.py', '.json', '.csv', '.html', '.log'):
                with open(path, 'r', encoding='utf-8') as f:
                    text = f.read()
            elif ext == '.docx' and DOCX_AVAILABLE:
                doc = Document(path)
                text = '\n'.join([p.text for p in doc.paragraphs])
            elif ext == '.pdf' and PDF_AVAILABLE:
                reader = PdfReader(path)
                text = '\n'.join([page.extract_text() or '' for page in reader.pages])
            elif ext == '.pptx' and PPTX_AVAILABLE:
                prs = Presentation(path)
                text_parts = []
                for slide in prs.slides:
                    for shape in slide.shapes:
                        if shape.has_text_frame:
                            for para in shape.text_frame.paragraphs:
                                line = "".join(run.text for run in para.runs)
                                if line.strip():
                                    text_parts.append(line)
                text = '\n'.join(text_parts)
            else:
                with open(path, 'r', encoding='utf-8', errors='ignore') as f:
                    text = f.read()

            # Дополнительно: извлекаем таблицы и добавляем как Markdown
            if text:
                try:
                    tables_md = self.extract_tables_from_file(path)
                    if tables_md:
                        text = text + "\n\n" + "\n\n".join(tables_md)
                except Exception as e:
                    logger.warning(f"[File] Ошибка извлечения таблиц из {path}: {e}")

            return text if text.strip() else None
        except Exception as e:
            logger.warning(f"[File] Ошибка чтения файла {path}: {e}")
            return None

    def extract_images_from_file(self, path):
        """Извлекает изображения из PDF или DOCX и возвращает список data URI."""

        images = []
        ext = os.path.splitext(path)[1].lower()
        try:
            if ext == '.pdf' and PDF_IMAGES_AVAILABLE:
                pdf = pdfium.PdfDocument(path)
                try:
                    for page_index in range(len(pdf)):
                        page = pdf[page_index]
                        try:
                            objects = page.get_objects()
                        except Exception:
                            continue
                        for obj in objects:
                            if not isinstance(obj, pdfium.PdfImage):
                                continue
                            try:
                                bitmap = obj.get_bitmap(render=False)
                                pil_image = bitmap.to_pil()
                                buffer = io.BytesIO()
                                pil_image.save(buffer, format="PNG")
                                img_bytes = buffer.getvalue()
                                data_uri = "data:image/png;base64," + base64.b64encode(img_bytes).decode('utf-8')
                                images.append(data_uri)
                            except Exception as e:
                                self.logger.warning(f"Не удалось извлечь картинку из PDF: {e}")
                                continue
                finally:
                    pdf.close()
            elif ext == '.docx' and DOCX_AVAILABLE:
                doc = Document(path)
                for rel in doc.part.rels.values():
                    if "image" in rel.reltype:
                        image_part = rel.target_part
                        img_bytes = image_part.blob
                        data_uri = "data:image/png;base64," + base64.b64encode(img_bytes).decode('utf-8')
                        images.append(data_uri)
            elif ext == '.pptx' and PPTX_AVAILABLE:
                prs = Presentation(path)
                for slide in prs.slides:
                    for shape in slide.shapes:
                        if shape.shape_type == 13:
                            image = shape.image
                            img_bytes = image.blob
                            data_uri = "data:image/png;base64," + base64.b64encode(img_bytes).decode('utf-8')
                            images.append(data_uri)
        except Exception as e:
            self.logger.warning(f"Ошибка извлечения изображений из {path}: {e}")
        return images

    def show_attachment_preview(self, attachment: dict):
        if attachment.get('type') == 'image':
            path = attachment.get('path')
            if not path or not os.path.exists(path):
                QMessageBox.warning(self, "Ошибка", "Файл не найден.")
                return
            try:
                with open(path, 'rb') as f:
                    raw = f.read()
                if raw.startswith(b"ENC:"):
                    raw = self._decrypt_bytes(raw)
                pixmap = QPixmap()
                pixmap.loadFromData(raw)
                if pixmap.isNull():
                    QMessageBox.warning(self, "Ошибка", "Не удалось загрузить изображение.")
                    return
                dialog = ImagePreviewDialog(pixmap, self)
                dialog.exec()
            except Exception as e:
                QMessageBox.warning(self, "Ошибка", f"Не удалось открыть изображение:\n{e}")
        else:
            dialog = MessagePreviewDialog("", [attachment], self, show_send_button=False)
            dialog.exec()

