    def update_chat_settings_button_visibility(self):
        has_chat = self.current_chat_index >= 0
        self.btn_chat_settings.setVisible(has_chat)
        if has_chat:
            self.position_chat_settings_button()
            self.btn_chat_settings.raise_()

    # ======================================================================
    #  ПОИСК И НАВИГАЦИЯ
    # ======================================================================

    def show_search_panel(self):
        if self.current_chat_index < 0:
            return
        self.search_panel.setVisible(True)
        self.search_edit.setFocus()
        self.search_edit.clear()
        self.search_counter_label.setText("0")
        self.update_search_panel_position()

    def _on_search_text_changed(self):
        """Сброс текущего индекса при изменении запроса."""

        self._current_search_idx = -1
        self._search_total = 0
        self.update_search_counter()

    def close_search_panel(self):
        self.search_panel.setVisible(False)
        self.search_counter_label.setText("")
        self._current_search_idx = -1
        self._search_total = 0
        for fp, idx, widget in self.message_widgets:
            widget.apply_search_highlight("")

    def _restyle_search_panel(self):
        """Перекрашивает панель поиска под текущую тему.
        Вызывается при создании панели и при каждой смене темы."""

        dark = self.settings.get("theme", "light") == "dark"

        if dark:
            # Счётчик
            self.search_counter_label.setStyleSheet("""
                QLabel {
                    background-color: rgba(60, 60, 60, 0.9);
                    border: 1px solid #555;
                    border-radius: 8px;
                    padding: 2px 6px;
                    color: #e8eaed;
                    font-weight: bold;
                }
            """)
            # Чекбокс Regex
            self.check_regex.setStyleSheet("""
                QCheckBox {
                    color: #e8eaed;
                    font-weight: 600;
                    spacing: 6px;
                    padding: 2px 4px;
                }
                QCheckBox::indicator {
                    width: 16px;
                    height: 16px;
                    border: 1px solid #8a8a8a;
                    border-radius: 3px;
                    background-color: #3c3c3c;
                }
                QCheckBox::indicator:hover {
                    border-color: #8ab4f8;
                    background-color: #4a4a4a;
                }
                QCheckBox::indicator:checked {
                    background-color: #8ab4f8;
                    border-color: #8ab4f8;
                }
                QCheckBox::indicator:checked:hover {
                    background-color: #aecbfa;
                }
            """)
            # Поле ввода
            self.search_edit.setStyleSheet("""
                QLineEdit {
                    background-color: #3c3c3c;
                    color: #e8eaed;
                    border: 1px solid #555;
                    border-radius: 5px;
                    padding: 3px 6px;
                    selection-background-color: #8ab4f8;
                    selection-color: #000000;
                }
                QLineEdit:focus {
                    border: 1px solid #8ab4f8;
                }
            """)
        else:
            self.search_counter_label.setStyleSheet("""
                QLabel {
                    background-color: rgba(255, 255, 255, 0.7);
                    border: 1px solid #ccc;
                    border-radius: 8px;
                    padding: 2px 6px;
                    color: #333;
                    font-weight: bold;
                }
            """)
            self.check_regex.setStyleSheet("""
                QCheckBox {
                    color: #202124;
                    spacing: 6px;
                    padding: 2px 4px;
                }
                QCheckBox::indicator {
                    width: 16px;
                    height: 16px;
                    border: 1px solid #c8c8c8;
                    border-radius: 3px;
                    background-color: #ffffff;
                }
                QCheckBox::indicator:hover {
                    border-color: #1a73e8;
                }
                QCheckBox::indicator:checked {
                    background-color: #1a73e8;
                    border-color: #1a73e8;
                }
            """)
