    def _on_provider_changed(self, index):
        """Смена провайдера в настройках: обновляет список моделей."""

        provider = self.combo_provider.currentData()
        if provider == "ollama":
            self._refresh_ollama_models()

    def _refresh_ollama_models(self):
        """Заполняет выпадающий список моделей Ollama (из кэша главного окна)."""

        if not hasattr(self, 'edit_model'):
            return

        current_text = self.edit_model.currentText() if self.edit_model.currentText() else self.settings.get("model",
                                                                                                             "")

        # Пытаемся взять кэш у главного окна
        main_window = self.parent()
        names = []
        if main_window and hasattr(main_window, '_get_cached_ollama_models'):
            names = main_window._get_cached_ollama_models() or []
            # Запускаем фоновое обновление, если кэш пуст
            if not names and hasattr(main_window, '_refresh_ollama_models_cache'):
                main_window._refresh_ollama_models_cache()

        # Fallback: если кэш недоступен — используем текущее значение как единственный item
        self.edit_model.blockSignals(True)
        self.edit_model.clear()
        if names:
            self.edit_model.addItems(sorted(names))
        if current_text:
            self.edit_model.setText(current_text)
        elif names:
            self.edit_model.setText(sorted(names)[0])
        self.edit_model.blockSignals(False)

